import { getElementAffinity } from "../core/element.js";
import { hasStatus, hpRatio } from "./unit.js";
/**
 * 簡易AI: クールタイムが明けている中で最も強力な(番号が大きい)スキルを優先する。
 * skill 0 は常にクールタイム無しなので必ずフォールバックとして使用可能。
 */
export const HEAL_SKILL_HP_THRESHOLD = 0.8;
export function chooseSkill(unit, allUnits = [unit]) {
    if (hasStatus(unit, "SKILL_LOCK"))
        return { skill: unit.def.skills[0], index: 0 };
    for (let i = 2; i >= 1; i -= 1) {
        if (unit.cooldowns[i] === 0) {
            const skill = unit.def.skills[i];
            // パッシブは「使う」ものではない。手番の行動として選ばない
            if (skill.passive || skill.automatic)
                continue;
            const hasHeal = skill.effects.some((effect) => effect.kind === "HEAL");
            const allies = allUnits.filter((candidate) => candidate.team === unit.team && candidate.alive);
            if (hasHeal && allies.every((ally) => hpRatio(ally) >= HEAL_SKILL_HP_THRESHOLD))
                continue;
            if (isRedundantBuff(unit, skill, allUnits))
                continue;
            return { skill, index: i };
        }
    }
    return { skill: unit.def.skills[0], index: 0 };
}
/**
 * **強化しかしないスキルを、もう掛かっている相手へ撃とうとしていないか。**
 *
 * 同じ強化は重ねがけしない決まりなので、全部すでに付いていて残りターンも
 * 足りているなら、配り直しても**何も起きない**(ターンすら伸びない)。
 * それなら1つ下のスキルを使うほうがよい。
 *
 * ダメージや回復を併せ持つスキルは対象にしない。強化が無駄でも殴る値打ちがある。
 * 弱体も対象にしない。確率で外れるので、入っていない可能性が残るため。
 */
function isRedundantBuff(unit, skill, allUnits) {
    const buffs = skill.effects.filter((effect) => effect.kind === "BUFF");
    if (buffs.length === 0 || buffs.length !== skill.effects.length)
        return false;
    const targets = chooseTargets(unit, skill, allUnits);
    if (targets.length === 0)
        return false;
    return targets.every((target) => buffs.every((buff) => target.effects.some((active) => active.kind === "BUFF" && active.stat === buff.stat && active.remainingTurns >= buff.durationTurns)));
}
/** スキルの対象タイプに応じて対象ユニットを選ぶ */
export function chooseTargets(unit, skill, allUnits) {
    const allies = allUnits.filter((u) => u.team === unit.team && u.alive);
    const enemies = allUnits.filter((u) => u.team !== unit.team && u.alive);
    switch (skill.target) {
        case "SELF":
            return [unit];
        case "ALL_ALLIES":
            return allies;
        case "ALL_ENEMIES":
            return enemies;
        case "SINGLE_ALLY": {
            const isAttackBuff = skill.effects.some((effect) => effect.kind === "BUFF" && effect.stat === "atk");
            if (isAttackBuff) {
                const preferred = allies.find((ally) => ally.def.primaryTarget)
                    ?? [...allies].sort((a, b) => b.def.stats.atk - a.def.stats.atk)[0];
                return preferred ? [preferred] : [];
            }
            const sorted = [...allies].sort((a, b) => hpRatio(a) - hpRatio(b));
            return sorted.length > 0 ? [sorted[0]] : [];
        }
        case "SINGLE_ENEMY": {
            const taunt = unit.statusEffects.find((effect) => effect.type === "TAUNT");
            if (taunt?.sourceId) {
                const source = enemies.find((enemy) => enemy.instanceId === taunt.sourceId);
                if (source)
                    return [source];
                unit.statusEffects = unit.statusEffects.filter((effect) => effect !== taunt);
            }
            /*
             * ターゲット集中。**単体攻撃の狙い先だけを引き受ける。**
             * 挑発の後に見るのは、挑発が「かけた本人に向かせる」強制で、
             * こちらは「自分に向けさせる」宣言だから。両方かかっている時は
             * 先に受けた強制のほうを優先する。全体攻撃には影響しない。
             */
            const focused = enemies.find((enemy) => hasStatus(enemy, "FOCUS"));
            if (focused)
                return [focused];
            const affinityScore = (target) => {
                const affinity = getElementAffinity(unit.def.element, target.def.element);
                if (affinity === "ADVANTAGE")
                    return 0;
                if (affinity === "NEUTRAL")
                    return 1;
                return 2;
            };
            const sorted = [...enemies].sort((a, b) => {
                if (skill.targetPriority === "LOWEST_HP")
                    return hpRatio(a) - hpRatio(b);
                if (skill.targetPriority === "DEF_DOWN") {
                    const aDown = a.effects.some((effect) => effect.kind === "DEBUFF" && effect.stat === "def") ? 0 : 1;
                    const bDown = b.effects.some((effect) => effect.kind === "DEBUFF" && effect.stat === "def") ? 0 : 1;
                    if (aDown !== bDown)
                        return aDown - bDown;
                }
                if (skill.targetPriority === "CURSED") {
                    const aCursed = (a.curses?.length ?? 0) > 0 ? 0 : 1;
                    const bCursed = (b.curses?.length ?? 0) > 0 ? 0 : 1;
                    if (aCursed !== bCursed)
                        return aCursed - bCursed;
                }
                const scoreDiff = affinityScore(a) - affinityScore(b);
                if (scoreDiff !== 0)
                    return scoreDiff;
                return hpRatio(a) - hpRatio(b);
            });
            return sorted.length > 0 ? [sorted[0]] : [];
        }
        default:
            return [];
    }
}

import { getElementAffinity, getElementMultiplier } from "../core/element.js";
import { SW_CRIT_SHIFT, SW_GLANCING_CHANCE, SW_GLANCING_MULTIPLIER, balanceFlags } from "../core/balanceFlags.js";
import { SCALE_REFERENCE } from "../core/skill.js";
import { CRIT_RATE_TAKEN_DOWN, CRIT_RATE_TAKEN_UP } from "../core/statusValues.js";
import { countDebuffs, getEffectiveStat, hasAnyBuff, hasStatus, passiveEffectOf, passiveHpDamageBonus, } from "./unit.js";
import { applyDefense, calculateBaseDamage, roundNormalDamage } from "./damageFormula.js";
/**
 * 相手や自分の**今の状態だけ**で決まる条件を判定する。
 *
 * クリティカル回数のような「そのスキルの解決の中で起きたこと」は
 * ここでは見ない(ダメージ計算はヒットごとに走るので、まだ結果が出ていない)。
 * それらは戦闘側が解決の文脈を持って判定する。
 */
export function evaluateTargetCondition(condition, source, target) {
    const targetRatio = target.currentHp / target.maxHp;
    switch (condition) {
        case "TARGET_HAS_DEBUFF": return countDebuffs(target) > 0;
        case "TARGET_SPD_DOWN": return target.effects.some((e) => e.kind === "DEBUFF" && e.stat === "spd");
        case "TARGET_POISONED": return target.poisonStacks > 0;
        case "TARGET_TAUNTED": return hasStatus(target, "TAUNT");
        case "TARGET_HAS_BUFF": return hasAnyBuff(target);
        case "TARGET_HP_BELOW_50": return targetRatio <= 0.5;
        case "TARGET_HP_BELOW_30": return targetRatio <= 0.3;
        case "TARGET_HP_ABOVE_SELF": return targetRatio > source.currentHp / source.maxHp;
        case "TARGET_GAUGE_BELOW_20": return target.gauge <= 20;
        case "TARGET_GAUGE_ABOVE_50": return target.gauge >= 50;
        case "TARGET_DEBUFF_AT_LEAST_2": return countDebuffs(target) >= 2;
        case "TARGET_DEBUFF_AT_LEAST_3": return countDebuffs(target) >= 3;
        case "SELF_HP_ABOVE_50": return source.currentHp / source.maxHp >= 0.5;
        // 解決の文脈が要る条件は、ここでは判定できない
        case "ANY_CRIT":
        case "CRITS_AT_LEAST_2":
        case "CRITS_AT_LEAST_3":
        case "STUN_FAILED":
        case "KILLED_TARGET":
        case "STRIPPED_TARGET":
            return false;
    }
}
/**
 * 才能適応による被ダメージの軽減倍率。
 *
 * **同じ相手から連続で攻撃を受けるほど、その相手からのダメージが効かなくなる。**
 * 段数を進めるのも戻すのも `BattleEngine` の仕事で、ここは今の段を読むだけ
 * (ダメージ計算はヒットごとに走るので、ここで数えると多段攻撃1回で
 * 上限まで積み上がってしまう)。
 */
export function adaptationMultiplier(attacker, defender) {
    const trait = defender.def.bossTraits?.talentAdaptation;
    if (!trait)
        return 1;
    const stacks = defender.adaptationStacks?.get(attacker.instanceId) ?? 0;
    if (stacks <= 0)
        return 1;
    return 1 - Math.min(trait.maxReduction, stacks * trait.perStack);
}
export function getFinalCritRate(attacker, defender, skillBonus = 0) {
    const weak = passiveEffectOf(attacker);
    const conditionalCrit = weak?.kind === "WEAK_POINT" && defender.currentHp / defender.maxHp <= weak.hpRatio ? weak.critRate : 0;
    const rate = conditionalCrit + getEffectiveStat(attacker, "criRate")
        + skillBonus
        // 被クリ率の上げ下げ。**受ける側に付く**効果なので、名前の UP/DOWN は相手から見た向き
        + (hasStatus(defender, "CRIT_RATE_UP") ? CRIT_RATE_TAKEN_UP : 0)
        - (hasStatus(defender, "CRIT_RATE_DOWN") ? CRIT_RATE_TAKEN_DOWN : 0);
    return Math.max(0, Math.min(1, rate));
}
export function calcDamage(attacker, defender, effect, rng) {
    const atk = getEffectiveStat(attacker, "atk");
    const defenderRatio = defender.currentHp / defender.maxHp;
    // 対象のHPが下がるほど深く刺さる防御無視。当てはまるうち最も低い閾値の1つだけを使う
    const hpIgnore = [...(effect.targetHpIgnoreDefense ?? [])]
        .sort((a, b) => a.hpRatio - b.hpRatio)
        .find((tier) => defenderRatio <= tier.hpRatio);
    /*
     * 取り巻きが倒れて手に入れた防御無視も、ここで一緒に見る。
     * **足すのではなく大きい方を取る**——重ねると、防御役が
     * どれだけ積んでも意味を持たない相手が出来てしまう。
     */
    const weak = passiveEffectOf(attacker);
    const weakActive = weak?.kind === "WEAK_POINT" && defenderRatio <= weak.hpRatio;
    const debuffIgnore = effect.debuffIgnoreDefense && countDebuffs(defender) >= effect.debuffIgnoreDefense.count ? effect.debuffIgnoreDefense.ratio : 0;
    const ratio = Math.max(0, Math.min(1, Math.max(effect.ignoreDefenseRatio ?? 0, hpIgnore?.ratio ?? 0, attacker.deathBoostDefenseIgnore ?? 0, debuffIgnore, weakActive ? weak.ignore : 0)));
    const def = getEffectiveStat(defender, "def") * (1 - ratio);
    const scaleBonusStatValue = effect.scaleBonus
        ? effect.scaleBonus.stat === "hp"
            ? attacker.maxHp
            : getEffectiveStat(attacker, effect.scaleBonus.stat)
        : 0;
    // 基準値に対する割合。基準の半分なら上乗せも半分になる
    const prey = passiveEffectOf(attacker);
    const passiveSpeedBonus = prey?.kind === "SCENT_OF_PREY"
        ? (prey.speedCoefficient ?? 0) * getEffectiveStat(attacker, "spd") / 200 : 0;
    const scaleBonus = passiveSpeedBonus + (effect.scaleBonus
        ? effect.scaleBonus.bonusAtReference * (scaleBonusStatValue / SCALE_REFERENCE[effect.scaleBonus.stat])
        : 0);
    const dependentStat = effect.hpCoefficient !== undefined
        ? attacker.maxHp
        : effect.defCoefficient !== undefined
            ? getEffectiveStat(attacker, "def")
            : 0;
    // ベヒモスの「古代巨獣」は、HPが減るほど最大HP比例のダメージが伸びる
    const hpDamageBonus = effect.hpCoefficient !== undefined ? passiveHpDamageBonus(attacker) : 0;
    const coefficient = (effect.hpCoefficient ?? effect.defCoefficient ?? 0) * (1 + hpDamageBonus);
    const debuffCount = countDebuffs(defender);
    const debuffBonus = effect.debuffDamageBonus
        ? Math.min(effect.debuffDamageBonus.maxBonus, debuffCount * effect.debuffDamageBonus.perDebuff) : 0;
    /*
     * ここから下は「最終ダメージへの上乗せ」。
     * **足し算でまとめてから1度だけ掛ける。** 掛け算で重ねると、条件が2つ揃った時に
     * 想定の倍以上へ跳ねる(HP30%以下の相手に処刑技を撃った時が実際にそうなった)。
     */
    let finalBonus = (effect.finalDamageBonus ?? 0) + (effect.currentHpBonus ?? 0) * defenderRatio + (defenderRatio >= 1 ? effect.fullHpBonus ?? 0 : 0);
    if (prey?.kind === "REBIRTH")
        finalBonus += prey.damage * defenderRatio;
    if (prey?.kind === "ILLUSION" && ["LIGHT", "DARK"].includes(defender.def.element))
        finalBonus += .5;
    const hpTier = [...(effect.targetHpBonus ?? [])]
        .sort((a, b) => a.hpRatio - b.hpRatio)
        .find((tier) => defenderRatio <= tier.hpRatio);
    if (hpTier)
        finalBonus += hpTier.bonus;
    for (const entry of effect.conditionalBonus ?? []) {
        if (evaluateTargetCondition(entry.when, attacker, defender))
            finalBonus += entry.bonus;
    }
    if (effect.missingHpBonus) {
        const lost = 1 - attacker.currentHp / attacker.maxHp;
        finalBonus += Math.min(effect.missingHpBonus.maxBonus, lost * effect.missingHpBonus.perLostRatio);
    }
    // コボルトの「獲物の匂い」は、弱った相手を狙うほど深く刺さる
    const scent = passiveEffectOf(attacker);
    if (scent?.kind === "SCENT_OF_PREY" && defenderRatio <= scent.hpRatio)
        finalBonus += scent.damageUp;
    // 最終ダメージへの上乗せは、ATK項だけでなくHP/DEF比例の項にも同じように掛ける。
    // 片方だけに掛けると、HP比例が主のモンスターでは条件を満たしてもほとんど変わらない
    const perHitBase = calculateBaseDamage(atk, (effect.multiplier + scaleBonus) * (1 + debuffBonus), dependentStat, coefficient)
        * (1 + finalBonus);
    const hits = Math.max(1, Math.floor(effect.hits ?? 1));
    // 割合軽減は線形なのでhitごとの結果と同じ。固定軽減だけは解決全体で算出し均等配賦する。
    const resolutionDefense = applyDefense(perHitBase * hits, atk, def, effect.ignoreDefense);
    const afterDefense = resolutionDefense.afterDefense / hits;
    const affinity = getElementAffinity(attacker.def.element, defender.def.element);
    /*
     * sw方式では属性の倍率を使わない(相性はクリ率とかすりで表す)。
     * かすった時だけ 0.7 を掛ける。
     */
    const elementMultiplier = balanceFlags.elementMode === "sw"
        ? 1
        : getElementMultiplier(attacker.def.element, defender.def.element);
    /*
     * サマナーズウォー方式の属性相性。**倍率ではなく確率で効く。**
     * 有利はクリ率+15pt、不利はクリ率−15ptに加えて50%でかすり。
     * かすりは「ダメージ−30%・クリ不可・弱体不可」。
     */
    const swElement = balanceFlags.elementMode === "sw";
    const swCritBonus = swElement
        ? (affinity === "ADVANTAGE" ? SW_CRIT_SHIFT : affinity === "DISADVANTAGE" ? -SW_CRIT_SHIFT : 0)
        : 0;
    const isGlancing = swElement && affinity === "DISADVANTAGE" && rng() < SW_GLANCING_CHANCE;
    const isCrit = !isGlancing
        && rng() < getFinalCritRate(attacker, defender, (effect.critRateBonus ?? 0) + swCritBonus);
    const critMultiplier = isCrit ? (getEffectiveStat(attacker, "criDmg") + (weakActive ? weak.critDmg : 0)) * (1 + (effect.critDamageBonus ?? 0)) : 1;
    const dealtMultiplier = (attacker.def.combatMods?.damageDealtMultiplier ?? 1)
        // 高揚支援。**掛かっている間だけ**乗る
        * (attacker.damageDealtBonusTurns && attacker.damageDealtBonusTurns > 0
            ? 1 + (attacker.damageDealtBonus ?? 0) : 1);
    const takenMultiplier = (defender.def.combatMods?.damageTakenMultiplier ?? 1)
        * (defender.deathBoostDamageTaken ?? 1)
        * adaptationMultiplier(attacker, defender);
    // 軽減・パッシブによる被ダメージ減はここでは掛けない。
    // 無敵・シールド・かばうと同じ場所(applyIncomingDamage)で1度だけ掛ける
    const defensePassive = passiveEffectOf(defender);
    const critReduction = isCrit && defensePassive?.kind === "CHEAT" ? 1 - defensePassive.reduction : 1;
    const glancingMultiplier = isGlancing ? SW_GLANCING_MULTIPLIER : 1;
    const rawDamage = critReduction * afterDefense * elementMultiplier * glancingMultiplier * critMultiplier * dealtMultiplier * takenMultiplier;
    const damage = roundNormalDamage(rawDamage);
    return { damage, isCrit, affinity, isGlancing };
}

import { DEF_SW_BASE, balanceFlags } from "../core/balanceFlags.js";
/**
 * 入れ替える前の方式Eの係数。**いまは既定では通らない。**
 * `balanceFlags.defenseFormula` を `legacy` にした時だけ使われる比較用。
 */
export const DEFENSE_RATIO = 1.5;
export const FLAT_DEFENSE_RATIO = 0.25;
export const FLAT_DEFENSE_CAP = 0.25;
/** ATK/HP/DEFの独立項を合成する。途中では丸めない。 */
export function calculateBaseDamage(atk, atkMultiplier, dependentStat = 0, coefficient = 0) {
    return Math.max(0, atk) * Math.max(0, atkMultiplier) + Math.max(0, dependentStat) * Math.max(0, coefficient);
}
/**
 * 1対象・1スキル解決全体に対する防御計算。完全防御無視時は両軽減を0にする。
 *
 * 既定は `1000 / (1000 + 1.2 × DEF)`。`balanceFlags.defenseFormula` を
 * `legacy` にした時だけ、入れ替える前の方式Eへ戻る(前後を比べるため)。
 *
 * ## 2つの式は性質が違う
 *
 * 方式Eの軽減は**攻める側の攻撃力との比**で決まるので、攻撃を積めば相手の防御を抜ける。
 * いまの式は攻撃力を見ないため、**防御の値だけで軽減率が確定する。**
 * 同じDEF3,600でも、方式Eは攻撃力次第で40%前後、いまの式は常に81%軽減になる。
 * 数字の大小ではなく**この性質の違い**が難易度を動かす。
 *
 * **だから敵のDEFは式と対で決まっている。**塔も各ダンジョンも、入れ替えに合わせて
 * 実数を下げてある。片方だけ触ると崩れる(`docs/element-sw-plan-a.md`)。
 */
export function applyDefense(baseDamage, effectiveAtk, effectiveDef, ignoreDefense = false) {
    const base = Math.max(0, baseDamage);
    if (ignoreDefense)
        return { afterRatio: base, flatReduction: 0, afterDefense: base };
    if (balanceFlags.defenseFormula === "sw")
        return applyDefenseSw(base, effectiveDef);
    return applyDefenseLegacyE(base, effectiveAtk, effectiveDef);
}
/**
 * **いまの本番の式。** `1000 / (1000 + 1.2 × DEF)`。固定減算は持たない。
 * 攻撃力を受け取らないのは、**見ないから**。
 */
export function applyDefenseSw(baseDamage, effectiveDef) {
    const base = Math.max(0, baseDamage);
    const def = Math.max(0, effectiveDef);
    const afterRatio = base * DEF_SW_BASE / (DEF_SW_BASE + balanceFlags.swRatio * def);
    return { afterRatio, flatReduction: 0, afterDefense: Math.max(0, afterRatio) };
}
/**
 * **入れ替える前の方式E。**軽減が攻撃力との比で決まっていた頃の式。
 * 前後を並べて比べる検証ツールが直接呼ぶので、フラグを通さずに残してある。
 */
export function applyDefenseLegacyE(baseDamage, effectiveAtk, effectiveDef, ignoreDefense = false) {
    const base = Math.max(0, baseDamage);
    if (ignoreDefense)
        return { afterRatio: base, flatReduction: 0, afterDefense: base };
    const atk = Math.max(0, effectiveAtk);
    const def = Math.max(0, effectiveDef);
    const scaledDef = def * DEFENSE_RATIO;
    const afterRatio = scaledDef + atk > 0 ? base * atk / (scaledDef + atk) : base;
    const flatReduction = Math.min(def * FLAT_DEFENSE_RATIO, afterRatio * FLAT_DEFENSE_CAP);
    return { afterRatio, flatReduction, afterDefense: Math.max(0, afterRatio - flatReduction) };
}
/** 通常防御計算の最終整数化。将来の完全無効(0)はこの関数を呼ばず区別する。 */
export function roundNormalDamage(value) {
    return Math.max(1, Math.round(value));
}

import { ELEMENT_JA } from "../core/element.js";
import { ATK_DOWN, DEF_DOWN, SPD_DOWN } from "../core/statusValues.js";
import { TOWER80_RULES } from "../data/trialTowerFloor80.js";
import { STATUS_EFFECT_CATEGORY, STATUS_EFFECT_JA } from "../core/skill.js";
