                this.pushEvent({ targetId: ally.instanceId, kind: "HEAL", amount: ally.currentHp - before });
            }
        }
        if (unit.alive && passive?.kind === "ILLUSION" && !extraTurn) {
            this.pushPassiveCue(unit);
            this.push(`${this.label(unit)} の「バトルイリュージョン」！`);
            const opening = { id: "illusion_opening", name: "バトルイリュージョン", description: "", target: "ALL_ENEMIES", cooldownTurns: 0,
                effects: [{ kind: "DAMAGE", multiplier: passive.damage }, { kind: "CURSE", chance: passive.chance }] };
            const resolution = newResolution();
            for (const enemy of this.units.filter(u => u.alive && u.team !== unit.team))
                this.applySkillEffects(unit, enemy, opening, false, false, undefined, resolution);
        }
    }
    takeTurn(unit, choice, extraTurn = false) {
        if (!unit.alive)
            return;
        const wasPrepared = this.interactivePreparedTurns.delete(unit);
        if (!wasPrepared)
            this.applyTurnStart(unit, extraTurn);
        let acted = false;
        if (!unit.alive) {
            // 毒などで手番開始時に力尽きた場合、この手番はここで終わる
        }
        else if (unit.stunTurns > 0) {
            unit.stunTurns -= 1;
            this.push(`${this.label(unit)} はスタン中で行動できない！`);
        }
        else {
            this.applyTrialBossAction(unit);
            this.act(unit, choice);
            acted = true;
        }
        this.applyBurnAtTurnEnd(unit);
        if (acted)
            this.onUnitActed(unit);
    }
    /* ============================ パッシブ ============================ */
    /**
     * 誰かが1手番を終えた時に呼ぶ。「味方が行動するたび」「敵が行動するたび」の
     * パッシブをここ1か所で捌く。
     *
     * **手番の単位で1回。** 行動の中の1発ごとに数えると、多段攻撃を持つ相手が
     * 動いただけでゲージが満ちてしまう。
     */
    onUnitActed(actor) {
        // 70階の再生は「始祖ベヒモス自身が実際に行動した手番の終了時」だけ。
        // スタンで行動できなかった時や、取り巻きの手番では進めない。
        if (this.isTower70Boss(actor))
            this.applyTower70BossRegen(actor);
        /*
         * 100階。分身が倒れた瞬間を拾うのは**誰の手番の後でも**必要になる。
         * 分身を倒すのはこちらなので、ボスの手番だけ見ていては1手遅れる
         */
        if (this.trialTowerFloor === 100) {
            this.syncTower100CloneDeaths();
            this.applyTower100LowHpTempo(actor);
            const boss = this.trialBoss();
            if (boss)
                this.syncTower100Boss(boss);
        }
        /*
         * 追加攻撃。**確率でスキル1をもう一度撃つ。**
         *
         * 追加ターンと違い、**手番そのものは増えない**(1つの技の中で
         * もう一撃だけ出る)。反撃の中では起こさない——反撃から反撃を
         * 呼び続ける形になり、盤面が止まらなくなる。
         */
        const followUp = this.lastUsedSkill?.talentMods?.followUpS1Chance ?? 0;
        if (actor.alive && followUp > 0 && this.counterDepth === 0 && this.rng() < followUp) {
            const s1 = actor.def.skills[0];
            if (s1 && !s1.passive) {
                this.push(`  → ${this.label(actor)} の追加攻撃！`);
                this.counterDepth += 1;
                try {
                    const targets = chooseTargets(actor, s1, this.units);
                    const resolution = newResolution();
                    targets.forEach((t, i) => this.applySkillEffects(actor, t, s1, false, i === 0, undefined, resolution));
                }
                finally {
                    this.counterDepth -= 1;
                }
            }
        }
        /*
         * 再行動。装備・ボス特性に加えて、**その手番で撃った技の才能**も見る。
         * `usedSkill` はこの手番で実際に使った技(パッシブや反撃は含まない)。
         */
        const extraTurnChance = Math.max(actor.def.combatMods?.extraTurnChance ?? 0, actor.def.bossTraits?.extraTurnChance ?? 0, this.lastUsedSkill?.talentMods?.extraTurnChance ?? 0);
        if (actor.alive && extraTurnChance > 0 && this.rng() < extraTurnChance) {
            this.pendingExtraTurns.push(actor);
        }
        for (const holder of this.units) {
            if (!holder.alive || holder === actor)
                continue;
            const passive = passiveEffectOf(holder);
            if (!passive)
                continue;
            if (passive.kind === "TIME_KEEPER" && holder.team === actor.team) {
                this.pushPassiveCue(holder);
                this.gainGauge(holder, passive.allyGauge, `${this.label(holder)} の「時の管理者」で行動ゲージが進んだ！`);
            }
            if (passive.kind === "GAUGE_ON_SLOWED_ENEMY_ACT" && holder.team !== actor.team) {
                const slowed = actor.effects.some((effect) => effect.kind === "DEBUFF" && effect.stat === "spd");
                if (slowed) {
                    this.pushPassiveCue(holder);
                    this.gainGauge(holder, passive.gauge, `${this.label(holder)} の「蛇王の支配」で行動ゲージが進んだ！`);
                }
            }
        }
    }
    /** 敵が毒ダメージを受けた時に呼ぶ。**その敵の手番につき1回**(毒は手番開始時にしか刻まれない) */
    onPoisonDamage(victim) {
        for (const holder of this.units) {
            if (!holder.alive || holder.team === victim.team)
                continue;
            const passive = passiveEffectOf(holder);
            if (passive?.kind !== "GAUGE_ON_ENEMY_POISON")
                continue;
            this.pushPassiveCue(holder);
            this.gainGauge(holder, passive.gauge, `${this.label(holder)} の「菌糸支配」で行動ゲージが進んだ！`);
        }
    }
    /**
     * 攻撃を受けた時に呼ぶ。**1回の攻撃(=攻撃者の1行動)につき1度だけ。**
     * 多段で殴られるたびに回復や反撃が返ると、手数の多い相手ほど損をする。
     */
    onDamaged(victim, attacker, resolutionKey) {
        // 潜在能力で溜まる「次のスキル1への上乗せ」は、被弾のたびに1段ずつ増える
        const latent = victim.def.latentAbility;
        if (latent?.chargeOnHit) {
            victim.latentChargeBonus = Math.min(latent.chargeOnHit.maxBonus, victim.latentChargeBonus + latent.chargeOnHit.perHit);
        }
        if (victim.hitGaugeTurns > 0 && victim.alive)
            this.gainGauge(victim, victim.hitGaugeAmount);
        if (!attacker?.alive || !victim.alive)
            return;
        const passive = passiveEffectOf(victim);
        const already = resolutionKey?.victimPassiveUsed.has(victim.instanceId) ?? false;
        if (passive?.kind === "FALSE_TREASURE" && !already) {
            resolutionKey?.victimPassiveUsed.add(victim.instanceId);
            this.pushPassiveCue(victim);
            const healAmount = Math.round(victim.maxHp * passive.heal);
            applyHeal(victim, healAmount);
            this.push(`  → ${this.label(victim)} の「偽りの財宝」でHPが ${healAmount} 回復！ (${victim.currentHp}/${victim.maxHp})`);
            this.pushEvent({ targetId: victim.instanceId, kind: "HEAL", amount: healAmount });
            if (!this.isImmune(attacker) && this.rollEffectSuccess(victim, attacker, passive.chance)) {
                applyStatEffect(attacker, "atk", -passive.atkDown, passive.duration, "DEBUFF");
                this.push(`  → ${this.label(attacker)} の ATK が低下！ (${passive.duration}ターン)`);
            }
        }
    }
    /** 味方(自分を含む)がHP閾値を割った時に呼ぶ。ヴァルキリアの「戦乙女の誓い」 */
    onAllyHpThreshold(victim) {
        if (!victim.alive)
            return;
        for (const holder of this.units) {
            if (!holder.alive || holder.team !== victim.team)
                continue;
            const passive = passiveEffectOf(holder);
            if (passive?.kind !== "VALKYRIE_OATH")
                continue;
            if (holder.passiveCooldown > 0)
                continue;
            if (hpRatio(victim) > passive.hpRatio)
                continue;
            holder.passiveCooldown = passive.internalCooldown;
            this.pushPassiveCue(holder);
            // 無敵は1ターン固定。Lv5でも伸ばさない(依頼主の指定)
            applyStatus(victim, "INVINCIBLE", 1, holder.instanceId);
            const healAmount = Math.round(holder.maxHp * passive.heal);
            applyHeal(victim, healAmount);
            this.push(`  → ${this.label(holder)} の「戦乙女の誓い」！ ${this.label(victim)} は1ターン無敵になり、HPが ${healAmount} 回復！`);
            this.pushEvent({ targetId: victim.instanceId, kind: "HEAL", amount: healAmount });
            return;
        }
    }
    /** 敵を倒した時に呼ぶ。フェンリルの「群狼の本能」は倒すたびに追加ターンを得る */
    onKill(killer) {
        if (!killer?.alive)
            return;
        const passive = passiveEffectOf(killer);
        if (passive?.kind === "SKY_RULER") {
            killer.skyStacks = Math.min(8, (killer.skyStacks ?? 0) + 1);
            this.pushPassiveCue(killer);
        }
        if (passive?.kind !== "PACK_INSTINCT")
            return;
        this.pushPassiveCue(killer);
        this.pendingExtraTurns.push(killer);
    }
    /** 攻撃1回の解決後に、祝福セットと支援型魔獣の一度きり回復を判定する。 */
    tryThresholdHeals(victim) {
        if (!victim.alive)
            return;
        const mods = victim.def.combatMods;
        if (!victim.thresholdHealUsed
            && (mods?.thresholdHealPercent ?? 0) > 0
            && hpRatio(victim) <= (mods?.thresholdHealHpRatio ?? 0)
            && !(victim.healBlockTurns > 0 && victim.healBlockMultiplier <= 0)) {
            victim.thresholdHealUsed = true;
            const before = victim.currentHp;
            applyHeal(victim, Math.round(victim.maxHp * (mods?.thresholdHealPercent ?? 0)));
            const healed = victim.currentHp - before;
            this.push(`  → ${this.label(victim)} の祝福が発動！ HPが ${healed} 回復！`);
            this.pushEvent({ targetId: victim.instanceId, kind: "HEAL", amount: healed });
        }
        for (const holder of this.units) {
            const trait = holder.def.bossTraits?.allyThresholdHeal;
            if (!trait || holder.team !== victim.team || !holder.alive || holder.allyThresholdHealUsed)
                continue;
            if (hpRatio(victim) > trait.hpRatio)
                continue;
            if (victim.healBlockTurns > 0 && victim.healBlockMultiplier <= 0)
                continue;
            holder.allyThresholdHealUsed = true;
            const before = victim.currentHp;
            applyHeal(victim, Math.round(victim.maxHp * trait.healPercent));
            const healed = victim.currentHp - before;
            this.push(`  → ${this.label(holder)} の「生命の祝福」！ ${this.label(victim)} のHPが ${healed} 回復！`);
            this.pushEvent({ targetId: victim.instanceId, kind: "HEAL", amount: healed });
            break;
        }
    }
    /**
     * 効果の向き先から、実際の受け手を決める。
     *
     * **ここ1本に集約してある。** 効果ごとに三項演算子を書き写していた頃は、
     * 新しい向き先を足すたびに書き漏らした場所だけが古い挙動のまま残った。
     */
    receiversFor(source, target, applyTo) {
        if (applyTo === "SELF")
            return [source];
        if (applyTo === "ALLIES")
            return this.units.filter((unit) => unit.team === source.team && unit.alive);
        if (applyTo === "LOWEST_HP_ALLY") {
            const allies = this.units.filter((unit) => unit.team === source.team && unit.alive);
            if (allies.length === 0)
                return [];
            return [allies.reduce((lowest, unit) => (hpRatio(unit) < hpRatio(lowest) ? unit : lowest), allies[0])];
        }
        return [target];
    }
    /** ゲージを増やす。100を超えて溜め込まないよう、増やす側は必ずここを通す */
    gainGauge(unit, amount, message) {
        if (!unit.alive || amount === 0)
            return;
        unit.gauge = Math.max(0, Math.min(ATB_THRESHOLD, unit.gauge + amount * ATB_THRESHOLD));
        if (message)
            this.push(`  → ${message}`);
    }
    trialBoss() {
        return this.units.find((u) => u.team === "ENEMY" && u.def.victoryTarget);
    }
    isTower70Boss(unit) {
        return this.trialTowerFloor === 70 && unit === this.trialBoss();
    }
    /** 70階のHP帯強化。段階は加算ではなく置き換え。 */
    tower70Tier(unit) {
        const ratio = hpRatio(unit);
        if (ratio <= 0.30)
            return { atk: 1500, spd: 45, hpFactor: 2.50 };
        if (ratio <= 0.50)
            return { atk: 1000, spd: 25, hpFactor: 1.60 };
        if (ratio <= 0.70)
            return { atk: 500, spd: 10, hpFactor: 1.30 };
        return { atk: 0, spd: 0, hpFactor: 1 };
    }
    syncTower70BossTier(unit) {
        if (!this.isTower70Boss(unit) || !unit.alive)
            return;
        const tier = this.tower70Tier(unit);
        unit.flatStatBonus.atk = tier.atk;
        unit.flatStatBonus.spd = tier.spd;
    }
    tower70HpCoefficientFactor(unit) {
        return this.isTower70Boss(unit) ? this.tower70Tier(unit).hpFactor : 1;
    }
    /* ======================================================================
     * 90階「狂化」。**お供を倒すとボスが強くなる階。**
     *
     * ここに書いてあるのは、3スキル枠に収まらない階固有の仕掛けだけ。
     * ダメージ計算も命中も抵抗もエンジンのまま——独自の計算式は1つも足さない。
     * **どのメソッドも `trialTowerFloor === 90` で入口を閉じてある。**
     * =================================================================== */
    isTower80Boss(unit) {
        return this.trialTowerFloor === 80 && unit.team === "ENEMY"
            && unit.def.skills.some((skill) => skill.id === "tower80_boss_s1");
    }
    grantTower80Immunity() {
        if (this.trialTowerFloor !== 80 || !this.units.some((unit) => this.isTower80Boss(unit) && unit.alive))
            return;
        for (const unit of this.units) {
            if (unit.team !== "ENEMY" || !unit.alive)
                continue;
            if (hasStatus(unit, "BUFF_BLOCK")) {
                this.push(`${this.label(unit)} は強化阻害で免疫の付与を防がれた！`);
                continue;
            }
            unit.immuneTurns = Math.max(unit.immuneTurns, TOWER80_RULES.immunityTurns);
        }
    }
    syncTower80Boss() {
        // 通常の強化・軽減を上書きしない。被ダメージ補正は着弾時に別途計算する。
        // Labの手番境界と異なり、HP閾値は被弾直後にも処理する。
        if (this.trialTowerFloor !== 80)
            return;
        const boss = this.units.find((unit) => this.isTower80Boss(unit));
        if (!boss?.alive)
            return;
        for (const unit of this.units) {
            if (unit.team === "ENEMY" && unit !== boss && !unit.alive)
                this.tower80DeadEscortIds.add(unit.instanceId);
        }
        for (const threshold of TOWER80_RULES.immunityThresholds) {
            if (hpRatio(boss) <= threshold && !this.tower80ImmunityThresholds.has(threshold)) {
                this.tower80ImmunityThresholds.add(threshold);
                this.grantTower80Immunity();
                this.push(`${this.label(boss)} の「聖竜の免疫」が再展開！`);
            }
        }
        boss.flatStatBonus.atk = boss.immuneTurns > 0 ? TOWER80_RULES.immuneAtkBonus : 0;
    }
    tower80DamageTakenFactor(unit) {
        if (!this.isTower80Boss(unit))
            return 1;
        return 1 + (unit.immuneTurns > 0 ? 0 : TOWER80_RULES.strippedDamageTaken)
            + Math.min(4, this.tower80DeadEscortIds.size) * TOWER80_RULES.escortKillDamageBonus;
    }
    isTower90Boss(unit) {
        return this.trialTowerFloor === 90 && unit === this.trialBoss();
    }
    /** その名前のお供が生きているか。並び順ではなくスキルIDで見分ける */
    tower90EscortAlive(skillId) {
        return this.units.some((unit) => unit.team === "ENEMY" && unit.alive && unit.def.skills.some((skill) => skill.id === skillId));
    }
    /**
     * 倒したお供の数。**一度倒れた相手を覚えておく。**
     *
     * 生存数から引く形にすると、蘇生や再戦で数が戻った時に狂化も戻ってしまう。
     * 「1体倒すごとに永久加算」なので、**戻らないこと**が仕様の一部。
     * 覚えておく場所はエンジンのインスタンスなので、
     * 戦闘をやり直せば新しいエンジンとともに白紙へ戻る(二重適用しない)。
     */
    tower90CountEscortDeaths() {
        if (this.trialTowerFloor !== 90)
            return 0;
        for (const unit of this.units) {
            if (unit.team !== "ENEMY" || unit.alive || unit.def.victoryTarget)
                continue;
            this.tower90DeadEscortIds.add(unit.instanceId);
        }
        return this.tower90DeadEscortIds.size;
    }
    /**
     * ボスの狂化を張り直す。**HP帯とお供死亡は別枠で、同時に効く。**
     * HP帯は加算式(70%以下 +1,000 / 40%以下 さらに +2,000 / 20%以下 さらに +2,000)。
     */
    syncTower90Boss(unit) {
        if (!this.isTower90Boss(unit) || !unit.alive)
            return;
        const ratio = hpRatio(unit);
        let atk = 0;
        let spd = 0;
        if (ratio <= 0.70) {
            atk += TOWER90_RAGE_HP70_ATK;
            spd += TOWER90_RAGE_HP70_SPD;
        }
        if (ratio <= 0.40) {
            atk += TOWER90_RAGE_HP40_ATK;
            spd += TOWER90_RAGE_HP40_SPD;
        }
        if (ratio <= 0.20) {
            atk += TOWER90_RAGE_HP20_ATK;
            spd += TOWER90_RAGE_HP20_SPD;
        }
        const kills = this.tower90CountEscortDeaths();
        unit.flatStatBonus.atk = atk + kills * TOWER90_ESCORT_DEATH_ATK;
        unit.flatStatBonus.spd = spd + kills * TOWER90_ESCORT_DEATH_SPD;
        unit.flatStatBonus.criRate = kills * TOWER90_ESCORT_DEATH_CRI_RATE;
        unit.flatStatBonus.criDmg = kills * TOWER90_ESCORT_DEATH_CRI_DMG;
    }
    /**
     * ボスの与ダメージ倍率。**段階式で、掛け算では積まない。**
     * 40%以下は×1.25、20%以下は×1.5(1.25×1.5=1.875 にはしない)。
     * 40%より上の×0.90は序盤の抑制で、これが無いと判断する前に押し切られる。
     */
    tower90BossDamageFactor(unit) {
        if (!this.isTower90Boss(unit))
            return 1;
        const ratio = hpRatio(unit);
        if (ratio <= 0.20)
            return TOWER90_RAGE_HP20_DAMAGE_FACTOR;
        if (ratio <= 0.40)
            return TOWER90_RAGE_HP40_DAMAGE_FACTOR;
        return TOWER90_EARLY_DAMAGE_FACTOR;
    }
    /** 戦鼓晶が倒れた後、狂牙獣が生きている間だけ乗る強化 */
    syncTower90Fang() {
        if (this.trialTowerFloor !== 90)
            return;
        const fang = this.units.find((unit) => unit.team === "ENEMY" && unit.def.skills.some((skill) => skill.id === TOWER90_FANG_EXECUTE_SKILL_ID));
        if (!fang)
            return;
        const enraged = fang.alive && !this.tower90EscortAlive(TOWER90_WAR_DRUM_TEMPO_SKILL_ID);
        fang.flatStatBonus.atk = enraged ? TOWER90_FANG_RAGE_ATK : 0;
        fang.flatStatBonus.spd = enraged ? TOWER90_FANG_RAGE_SPD : 0;
    }
    /** 戦鼓晶が倒れていて狂牙獣が生きているか(処刑突撃だけを2.9倍にする条件) */
    isTower90FangEnraged(unit) {
        if (this.trialTowerFloor !== 90 || !unit.alive)
            return false;
        if (!unit.def.skills.some((skill) => skill.id === TOWER90_FANG_EXECUTE_SKILL_ID))
            return false;
        return !this.tower90EscortAlive(TOWER90_WAR_DRUM_TEMPO_SKILL_ID);
    }
    /**
     * 戦鼓晶S3「血戦共鳴」の、**ボスにだけ渡すぶん。**
     * 全体へのゲージ30%はスキル定義の側が配る。ここはボス限定の上乗せで、
     * お供へCT短縮を配ってしまうと縛晶の妨害まで回転が上がって別物の階になる。
     */
    applyTower90WarDrumTempo() {
        const boss = this.trialBoss();
        if (!boss || !boss.alive)
            return;
        boss.gauge = Math.min(ATB_THRESHOLD, boss.gauge + TOWER90_WAR_DRUM_BOSS_GAUGE * ATB_THRESHOLD);
        for (let i = 0; i < boss.cooldowns.length; i += 1) {
            boss.cooldowns[i] = Math.max(0, boss.cooldowns[i] - TOWER90_WAR_DRUM_BOSS_COOLDOWN);
        }
        this.push(`  → ${this.label(boss)} は血戦共鳴で行動ゲージとスキルの回転を得た！`);
    }
    /* ======================================================================
     * 100階「クリモアーク」。**戦っている最中に敵が増える唯一の階。**
     *
     * 増やす機構はエンジンに無い(盤面・HPの札・行動順UI・勝敗判定のどれもが
     * 開幕に決まった顔ぶれを前提にしている)。代わりに**空席を先に2つ置いて
     * 眠らせておき**、スキル3で起こす。顔ぶれの数は最初から最後まで変わらない。
     *
     * **どのメソッドも `trialTowerFloor === 100` で入口を閉じてある。**
     * =================================================================== */
    /** 開幕の仕込み。分身の空席を眠らせ、スキル4のクールタイムを立てる */
    setupTower100() {
        const boss = this.trialBoss();
        if (!boss)
            return;
        for (const unit of this.units) {
            if (unit.team !== "ENEMY" || unit === boss)
                continue;
            unit.alive = false;
            unit.currentHp = 0;
            unit.gauge = 0;
            this.tower100Clones.push({ unit, role: null, everSpawned: false, previousAlive: false });
        }
        /*
         * 開幕からスキル4を撃たせない。**通常のクールタイムより1手だけ短い**ので、
         * 「S3で分身を出す → S4」という並びに落ち着く
         */
        this.tower100S4Cooldown = CRIMOARK_S4_COOLDOWN - 1;
