    isTower100Boss(unit) {
        return this.trialTowerFloor === 100 && unit === this.trialBoss();
    }
    /** その席がいま起きている分身か */
    tower100CloneOf(unit) {
        if (this.trialTowerFloor !== 100)
            return undefined;
        return this.tower100Clones.find((slot) => slot.unit === unit);
