            return;
        this.trialBossTurns += 1;
        const ratio = hpRatio(unit);
        if (this.trialTowerFloor === 70) {
            // 旧実装の「毎手番72%超再生」は廃止。V7確定仕様は行動終了時3%（生命晶生存中は7%）。
            this.syncTower70BossTier(unit);
            return;
        }
