         * 狂牙獣の処刑突撃だけ 2.6 → 2.9 倍。**S1・S2は据え置く。**
         * 全部を底上げすると「瀕死を刈る役」ではなくただの高火力役になる。
         */
        if (skill.id === TOWER90_FANG_EXECUTE_SKILL_ID && this.isTower90FangEnraged(unit)) {
            resolvedSkill = {
                ...resolvedSkill,
                effects: resolvedSkill.effects.map((effect) => effect.kind === "DAMAGE"
                    ? { ...effect, multiplier: TOWER90_FANG_EXECUTE_RAGE_MULTIPLIER }
                    : effect),
            };
        }
        /*
         * 100階。**スキル4は3枠の外側にある。**
         *
         * 全モンスターを4枠へ広げると、UI・AI・スキル継承・セーブのすべてが
         * 「3つ」を前提にしているところへ手が入る。ここでは撃つ瞬間だけ
         * スキル4の定義を差し込み、枠そのものは3つのまま置いておく。
         */
        if (this.isTower100Boss(unit)) {
            this.syncTower100Boss(unit);
            if (this.tower100UseS4) {
                // 生存している分身1体につき最終ダメージ+15%
                const bonus = this.tower100AliveClones().length * CRIMOARK_S4_CLONE_BONUS;
                /*
                 * **枠のクールタイムは触らせない。**`cooldownTurns` を 0 にした写しを渡す。
                 * 6のまま渡すと `unit.cooldowns[2] = 6` が走り、
                 * スキル3(クリエイト・コピー)まで6ターン止まる。
                 * スキル4の待ち時間は `tower100S4Cooldown` が別に数えている
                 */
                skill = { ...CRIMOARK_S4, cooldownTurns: 0 };
                resolvedSkill = bonus > 0
                    ? { ...skill, effects: CRIMOARK_S4.effects.map((effect) => effect.kind === "DAMAGE"
                            ? { ...effect, finalDamageBonus: (effect.finalDamageBonus ?? 0) + bonus }
                            : effect) }
                    : skill;
                this.tower100S4Cooldown = CRIMOARK_S4_COOLDOWN;
                this.tower100UseS4 = false;
            }
            else {
                this.tower100S4Cooldown = Math.max(0, this.tower100S4Cooldown - 1);
            }
            const factor = this.tower100BossDamageFactor(unit);
            if (factor !== 1) {
                resolvedSkill = {
                    ...resolvedSkill,
                    effects: resolvedSkill.effects.map((effect) => effect.kind === "DAMAGE"
                        ? { ...effect, multiplier: effect.multiplier * factor }
                        : effect),
                };
            }
        }
        const tower70BossS3AboveHalf = this.isTower70Boss(unit)
            && skill.id === "tower70_behemoth_s3"
            && hpRatio(unit) >= 0.5;
        const ignoreChance = Math.max(unit.def.combatMods?.defenseIgnoreChance ?? 0, unit.def.bossTraits?.defenseIgnoreChance ?? 0);
        const ignoreRatio = Math.max(unit.def.combatMods?.defenseIgnoreRatio ?? 0, unit.def.bossTraits?.defenseIgnoreRatio ?? 0);
        if (ignoreChance > 0 && ignoreRatio > 0 && resolvedSkill.effects.some((effect) => effect.kind === "DAMAGE") && this.rng() < ignoreChance) {
            resolvedSkill = { ...resolvedSkill, effects: resolvedSkill.effects.map((effect) => effect.kind === "DAMAGE"
                    ? { ...effect, ignoreDefenseRatio: Math.max(effect.ignoreDefenseRatio ?? 0, ignoreRatio) }
                    : effect) };
        }
        if (index === 0)
            unit.latentChargeBonus = 0;
        let targets;
        if (skill.randomEnemyHits) {
            const enemies = this.units.filter((candidate) => candidate.team !== unit.team && candidate.alive);
            const hitCount = resolvedSkill.effects.find((effect) => effect.kind === "DAMAGE")?.hits ?? 1;
            targets = Array.from({ length: hitCount }, () => enemies[Math.floor(this.rng() * enemies.length)]).filter(Boolean);
            resolvedSkill = { ...resolvedSkill, effects: resolvedSkill.effects.map((effect) => effect.kind === "DAMAGE" ? { ...effect, hits: 1 } : effect) };
        }
        else if (choice?.targetId && (skill.target === "SINGLE_ENEMY" || skill.target === "SINGLE_ALLY")) {
            const explicitTarget = this.units.find((u) => u.instanceId === choice.targetId && u.alive);
            targets = explicitTarget ? [explicitTarget] : chooseTargets(unit, skill, this.units);
        }
        else {
            targets = chooseTargets(unit, skill, this.units);
            if (unit.team === "PLAYER" && skill.target === "SINGLE_ENEMY" && !hasStatus(unit, "TAUNT")) {
                const focused = this.units.find((candidate) => candidate.instanceId === this.getFocusTarget() && candidate.alive);
                if (focused)
                    targets = [focused];
            }
        }
        if (skill.target === "SINGLE_ENEMY") {
            const forced = chooseTargets(unit, skill, this.units)[0];
            const taunt = unit.statusEffects.some((effect) => effect.type === "TAUNT");
            if (taunt && forced && targets[0] !== forced) {
                targets = [forced];
                this.push(`  → 挑発により対象が ${this.label(forced)} へ変更された！`);
            }
        }
        const aoeConverted = Boolean(latent?.aoeConversion && skill.target === "SINGLE_ENEMY");
        if (aoeConverted && targets[0]) {
            const primary = targets[0];
            targets = [primary, ...this.units.filter((candidate) => candidate.team !== unit.team && candidate.alive && candidate !== primary)];
        }
        if (targets.length === 0)
            return;
        if (skill.cooldownTurns > 0) {
            /*
             * 再使用補助。**確率でこの枠のクールタイムを1縮める。**
             * 置く場所をここにしてあるのは、CTを入れた直後でなければ
             * 「縮める」が成立しないから(あとで縮めると、既に減った分と混ざる)。
             */
            const refund = skill.talentMods?.cooldownRefundChance;
            const saved = refund && this.rng() < refund ? 1 : 0;
            unit.cooldowns[index] = Math.max(0, skill.cooldownTurns - saved);
            if (saved > 0)
                this.push(`  → ${this.label(unit)} の「${skill.name}」のクールタイムが縮まった！`);
        }
        /*
         * この手番で実際に使った技。**反撃やパッシブでは書き換えない。**
         * 「使用時に確率で追加ターン」を手番の終わりで判定するために要る。
         */
        if (this.counterDepth === 0)
            this.lastUsedSkill = skill;
        this.pushCue(unit, skill.name, "SKILL");
        this.push(`${this.label(unit)} の「${skill.name}」！`);
        if (this.trialTowerFloor === 70 && unit.team === "ENEMY" && skill.id === "tower70_pulse_s2") {
            this.applyTower70PulseCrush();
            return;
        }
        // 90階の戦鼓晶S3。全体ゲージ30%はスキル定義が配り、ここはボス限定の上乗せ
        const tower90WarDrumTempo = this.trialTowerFloor === 90
            && unit.team === "ENEMY"
            && skill.id === TOWER90_WAR_DRUM_TEMPO_SKILL_ID;
        // 100階。分身の生成と、分身から本体だけへ渡すぶんは技のIDで見分ける
        const tower100Copy = this.isTower100Boss(unit) && skill.id === CRIMOARK_S3_ID;
        const tower100CloneSkillId = this.trialTowerFloor === 100 && this.tower100CloneOf(unit) ? skill.id : null;
        // 暗闇がかかっていると、攻撃するたびに外れ判定が入る。
        // 外れた場合はこの手番のあいだ、ダメージが大きく下がり追加効果も乗らない。
        let missed = false;
        if (unit.blindTurns > 0 && this.rng() < BLIND_MISS_CHANCE) {
            missed = true;
            this.push(`  → ${this.label(unit)} は暗闇で手元が狂った！`);
        }
        // 効果の解決は対象ごとに1回ずつ走る。そのため「術者や味方に向いた効果」
        // (自己回復・applyToがSELF/ALLIESのバフ)を素直に処理すると、全体技では
        // 対象の数だけ重ねがけされてしまう(敵4体なら4倍)。
        // 向き先が対象でない効果は最初の1回だけ適用する。
        const resolution = newResolution();
        const previousResolution = this.resolution;
        this.resolution = resolution;
        const hpBeforeSkill = new Map(targets.map((target) => [target.instanceId, target.currentHp]));
        // 新しい全体攻撃の味方支援は、敵全体への攻撃を終えてから1回だけ配る。
        const deferred = resolvedSkill.levelOverrides && resolvedSkill.target === "ALL_ENEMIES"
            ? resolvedSkill.effects.filter(isSourceScopedEffect) : [];
        const directSkill = deferred.length ? { ...resolvedSkill, effects: resolvedSkill.effects.filter(e => !isSourceScopedEffect(e)) } : resolvedSkill;
        targets.forEach((target, i) => {
            const targetSkill = aoeConverted && latent?.aoeConversion ? { ...directSkill, effects: directSkill.effects
                    .filter((effect) => i === 0 || latent.aoeConversion?.nativeEffectTarget !== "PRIMARY_ONLY" || effect.kind === "DAMAGE")
                    .map((effect) => {
                    if (effect.kind === "DAMAGE")
                        return { ...effect, multiplier: effect.multiplier * latent.aoeConversion.damageMultiplier };
                    if (i > 0 && "chance" in effect && typeof effect.chance === "number")
                        return { ...effect, chance: effect.chance * (latent.aoeConversion.secondaryEffectChanceMultiplier ?? 1) };
                    return effect;
                }) } : directSkill;
            this.applySkillEffects(unit, target, targetSkill, missed, i === 0, latent, resolution);
        });
        if (deferred.length && unit.alive)
            this.applySkillEffects(unit, targets[0], { ...resolvedSkill, effects: deferred }, missed, true, undefined, resolution, true);
        if (this.isTower70Boss(unit) && skill.id === "tower70_behemoth_s3") {
            const removed = cleanseDebuffs(unit);
            if (removed > 0)
                this.push(`  → ${this.label(unit)} は自身の弱体効果をすべて解除した！`);
            if (tower70BossS3AboveHalf) {
                for (const enemy of this.units.filter((candidate) => candidate.team === "PLAYER" && candidate.alive)) {
                    enemy.gauge = Math.max(0, enemy.gauge - 0.2 * ATB_THRESHOLD);
                }
                this.push("  → 天地崩壊で味方全体の行動ゲージが20%後退した！");
            }
        }
        for (const target of new Set(targets)) {
            if (target.currentHp < (hpBeforeSkill.get(target.instanceId) ?? target.currentHp))
                this.tryThresholdHeals(target);
        }
        if (skill.resetCooldownOnKill && resolution.kills > 0)
            unit.cooldowns[index] = 0;
        if (skill.extraTurn && unit.alive)
            this.pendingExtraTurns.push(unit);
        if (skill.gaugeIfThreeEnemies && targets.length >= 3)
            this.gainGauge(unit, skill.gaugeIfThreeEnemies);
        if (skill.extraTurnOnKill && resolution.kills > 0 && unit.alive)
            this.pendingExtraTurns.push(unit);
        // 攻撃スキルに乗るパッシブは、対象を全部処理してから1度だけ判定する
        if (!missed)
            this.applyAttackPassives(unit, targets, resolution);
        if (latent && !missed)
            this.applyLatentAfterSkill(unit, targets[0], latent, resolution);
        // 90階の戦鼓晶S3。全体ゲージを配り終えた後で、ボスにだけ上乗せする
        if (tower90WarDrumTempo)
            this.applyTower90WarDrumTempo();
        if (this.isTower80Boss(unit) && unit.alive && skill.id === "tower80_boss_s3") {
            this.grantTower80Immunity();
            this.syncTower80Boss();
        }
        // 100階。分身を生む/立て直すのは技が解決し終わってから
        if (tower100Copy)
            this.applyTower100Copy(unit);
        if (tower100CloneSkillId)
            this.applyTower100CloneSupport(unit, tower100CloneSkillId, resolution.kills);
        this.applyCoopAttack(unit, resolvedSkill, targets[0]);
        this.resolution = previousResolution;
    }
    /** 溜めた上乗せを、そのスキルのダメージ効果へ差し込む */
    applyChargeToSkill(skill, charge) {
        if (charge <= 0)
            return skill;
        return { ...skill, effects: skill.effects.map((effect) => (effect.kind === "DAMAGE" ? { ...effect, finalDamageBonus: (effect.finalDamageBonus ?? 0) + charge } : effect)) };
    }
    /**
     * 攻撃スキルの使用に紐づくパッシブ。**1スキル使用につき1回**しか判定しない。
     *
     * ここを対象ごとに回すと、全体技を持つモンスターだけが4倍おいしくなる。
     * 依頼主の指定どおり、ゲージ吸収も追加デバフも1回に固定してある。
     */
    applyAttackPassives(source, targets, resolution) {
        const passive = passiveEffectOf(source);
        if (!passive || resolution.sourcePassiveUsed)
            return;
        const primary = targets.find((target) => target.alive && target.team !== source.team) ?? targets[0];
        if (!primary || primary.team === source.team)
            return;
        if (passive.kind === "THUNDER_INSTINCT" && resolution.anyCrit) {
            resolution.sourcePassiveUsed = true;
            this.pushPassiveCue(source);
            this.drainGauge(source, primary, passive.drain);
            this.push(`  → ${this.label(source)} の「雷の本能」で行動ゲージを吸収した！`);
        }
        if (passive.kind === "TIME_KEEPER" && resolution.damageDealt > 0) {
            resolution.sourcePassiveUsed = true;
            this.pushPassiveCue(source);
            // 全体攻撃なら、攻撃を受けて生き残った敵それぞれへ1回ずつ作用する。
            // Setで重複を除くため、同じ敵へ複数回当たる多段・ランダム攻撃でも
            // 吸収とスタンは1スキルにつき敵1体あたり1回まで。
            const affectedTargets = [...new Set(targets)]
                .filter((target) => target.alive && target.team !== source.team);
            for (const affected of affectedTargets) {
                const drained = this.drainGauge(source, affected, passive.drain);
                if (drained > 0) {
                    this.push(`  → ${this.label(source)} の「時の管理者」で行動ゲージを吸収した！ (対象: ${this.label(affected)})`);
                }
                if (!this.isImmune(affected) && this.rollEffectSuccess(source, affected, passive.stunChance)) {
                    affected.stunTurns = Math.max(affected.stunTurns, 1);
                    this.push(`  → ${this.label(affected)} はスタンした！`);
                }
            }
        }
        if (passive.kind === "REAPER_HARVEST" && resolution.damageDealt > 0 && primary.alive) {
            resolution.sourcePassiveUsed = true;
            let landed = false;
            if (!this.isImmune(primary)) {
                // 強化阻害・回復阻害はどちらも1ターン固定(依頼主の指定)
                if (this.rollEffectSuccess(source, primary, passive.chance) && applyStatus(primary, "BUFF_BLOCK", 1, source.instanceId)) {
                    this.push(`  → ${this.label(primary)} は強化不可になった！ (1ターン)`);
                    landed = true;
                }
                if (this.rollEffectSuccess(source, primary, passive.chance)) {
                    primary.healBlockTurns = Math.max(primary.healBlockTurns, 1);
                    primary.healBlockMultiplier = 0;
                    this.push(`  → ${this.label(primary)} は治癒阻害を受けた！ (1ターン)`);
                    landed = true;
                }
            }
            if (landed) {
                this.pushPassiveCue(source);
                const healAmount = Math.round(source.maxHp * passive.heal);
                applyHeal(source, healAmount);
                this.pushEvent({ targetId: source.instanceId, kind: "HEAL", amount: healAmount });
                this.gainGauge(source, passive.gauge);
                this.push(`  → ${this.label(source)} の「死神の収穫」でHPが ${healAmount} 回復し、行動ゲージが進んだ！`);
            }
        }
    }
    /** 相手のゲージを減らし、減らした分をそのまま自分へ移す */
    drainGauge(source, target, ratio) {
        if (!target.alive || ratio <= 0)
            return 0;
        const before = target.gauge;
        target.gauge = Math.max(0, target.gauge - ratio * ATB_THRESHOLD);
        const stolen = before - target.gauge;
        source.gauge = Math.max(0, Math.min(ATB_THRESHOLD, source.gauge + stolen));
        return stolen / ATB_THRESHOLD;
    }
    /**
     * 協力攻撃。呼ばれた味方は**それぞれのスキル1**で同じ相手を殴る。
     *
     * `coopDepth` で入れ子を止めている。呼ばれた側のスキル1が
     * また協力攻撃を呼べる形にすると、編成次第で無限に連鎖する。
     */
    applyCoopAttack(source, skill, target) {
        const coop = skill.effects.find((effect) => effect.kind === "COOP_ATTACK");
        if (!coop || !target || this.coopDepth > 0)
            return;
        const helpers = this.units
            .filter((unit) => unit.team === source.team && unit.alive && unit !== source && unit.stunTurns <= 0)
            .sort((a, b) => getEffectiveStat(b, "atk") - getEffectiveStat(a, "atk"))
            .slice(0, Math.max(0, coop.allies));
        if (helpers.length === 0)
            return;
        this.coopDepth += 1;
        try {
            for (const helper of helpers) {
                if (!target.alive)
                    break;
                this.push(`  → ${this.label(helper)} が協力攻撃に加わった！`);
                const helperSkill = helper.def.skills[0];
                const helperLatent = helper.def.latentAbility?.skillSlot === 0 ? helper.def.latentAbility : undefined;
                const resolved = this.applyChargeToSkill(helperLatent ? this.applyLatentToSkill(helperSkill, helperLatent) : helperSkill, helper.latentChargeBonus);
                helper.latentChargeBonus = 0;
                const resolution = newResolution();
                const previous = this.resolution;
                this.resolution = resolution;
                this.applySkillEffects(helper, target, resolved, false, true, helperLatent, resolution);
                this.applyAttackPassives(helper, [target], resolution);
                if (helperLatent)
                    this.applyLatentAfterSkill(helper, target, helperLatent, resolution);
                this.resolution = previous;
                if (coop.allyCooldownReduce) {
                    helper.cooldowns = helper.cooldowns.map((c) => Math.max(0, c - coop.allyCooldownReduce));
                }
            }
        }
        finally {
            this.coopDepth -= 1;
        }
    }
    /** ダメージ式・既存デバフ確率へ入る潜在だけを、元のS1を変更せず合成する。 */
    applyLatentToSkill(skill, latent) {
        let damageIndex = -1;
        return { ...skill, effects: skill.effects.map((effect) => {
                if (effect.kind === "DAMAGE") {
                    damageIndex += 1;
                    // 「2撃目だけ強くなる」型は、指定された順番のダメージ効果にしか乗らない
                    if (latent.damageEffectIndex !== undefined && latent.damageEffectIndex !== damageIndex)
                        return effect;
                    // 「対象のHPが低いほど痛い」型の潜在は、元の段を置き換える。
                    // 足すと元の段と二重に乗り、書いてある数字より大きく跳ねる
                    const withStatic = {
                        ...effect,
                        ignoreDefenseRatio: latent.ignoreDefenseRatio ?? effect.ignoreDefenseRatio,
                        debuffDamageBonus: latent.debuffDamageBonus ?? effect.debuffDamageBonus,
                        finalDamageBonus: (effect.finalDamageBonus ?? 0) + (latent.flatDamageBonus ?? 0),
                        conditionalBonus: latent.damageBonusWhen
                            ? [...(effect.conditionalBonus ?? []), ...latent.damageBonusWhen]
                            : effect.conditionalBonus,
                        targetHpBonus: latent.replaceTargetHpBonus ?? effect.targetHpBonus,
                        targetHpIgnoreDefense: latent.addTargetHpIgnoreDefense
                            ? [...(effect.targetHpIgnoreDefense ?? []), ...latent.addTargetHpIgnoreDefense]
                            : effect.targetHpIgnoreDefense,
                        scaleBonus: latent.scaleBonusAdd
                            ? {
                                stat: latent.scaleBonusAdd.stat,
                                bonusAtReference: (effect.scaleBonus?.stat === latent.scaleBonusAdd.stat ? effect.scaleBonus.bonusAtReference : 0)
                                    + latent.scaleBonusAdd.bonusAtReference,
                            }
                            : effect.scaleBonus,
                    };
                    if (latent.effectType === "DAMAGE_UP")
                        return { ...withStatic, multiplier: effect.multiplier * (1 + latent.value) };
                    if (latent.effectType === "HP_SCALING")
                        return { ...withStatic, hpCoefficient: (effect.hpCoefficient ?? 0) + latent.value };
                    if (latent.effectType === "DEF_SCALING")
                        return { ...withStatic, defCoefficient: (effect.defCoefficient ?? 0) + latent.value };
                    return withStatic;
                }
                if (effect.kind === "GAUGE" && latent.gaugeAmountOverride !== undefined) {
                    // 符号は元のまま。減らす技の潜在で、うっかり増やす技へ化けないようにする
                    const sign = effect.amount < 0 ? -1 : 1;
                    return { ...effect, amount: sign * Math.abs(latent.gaugeAmountOverride) };
                }
                const bonus = latent.chanceBonus;
                if (bonus && effect.kind === bonus.effectKind && (bonus.stat === undefined || ("stat" in effect && effect.stat === bonus.stat))) {
                    return { ...effect, chance: Math.min(1, (("chance" in effect ? effect.chance : undefined) ?? 1) + bonus.value) };
                }
                if (latent.effectType === "DEBUFF_CHANCE_UP" && latent.status === "DEF_DOWN"
                    && effect.kind === "DEBUFF" && effect.stat === "def") {
                    return { ...effect, chance: Math.min(1, (effect.chance ?? 1) + latent.value) };
                }
                return effect;
            }) };
    }
    /** 潜在能力の発動条件を、その1回の解決で起きたことに照らして判定する */
    latentConditionMet(latent, source, target, resolution) {
        const condition = latent.condition;
        if (!condition || condition.kind === "ALWAYS")
            return true;
        switch (condition.kind) {
            case "ON_CRIT": return resolution.critCount >= (condition.atLeast ?? 1);
            case "ON_KILL": return resolution.kills > 0;
            case "ON_APPLIED":
                return condition.status === "ANY_DEBUFF" ? resolution.debuffApplied : resolution.applied.has(condition.status);
            case "TARGET_HP_BELOW":
                return (resolution.targetHpBefore.get(target.instanceId) ?? target.currentHp / target.maxHp) <= condition.ratio;
            case "TARGET_STATE": return evaluateTargetCondition(condition.state, source, target);
        }
    }
    /**
     * S1使用後型の単一潜在効果を解決する。将来 effects[] になった場合は、この関数を
     * 各effectについて呼ぶだけでよく、使用回数単位の入口は変えない。
     */
    applyLatentAfterSkill(source, target, latent, resolution) {
        const anyCrit = resolution.anyCrit;
        const debuffApplied = resolution.debuffApplied;
        const allies = this.units.filter((unit) => unit.team === source.team && unit.alive);
        const lowestAlly = allies.reduce((lowest, unit) => hpRatio(unit) < hpRatio(lowest) ? unit : lowest, source);
        const receiver = latent.target === "SELF" ? source : latent.target === "LOWEST_HP_ALLY" ? lowestAlly : target;
        const proc = () => this.rng() < latent.chance;
        const announce = () => this.push(`  → 潜在能力「${latent.name}」が発動！`);
        // クリティカルで溜まる上乗せ・戦闘中ずっと残るクリダメは、条件判定より先に処理する
        if (latent.chargeOnCrit && resolution.critCount > 0) {
            source.latentChargeBonus = Math.min(latent.chargeOnCrit.maxBonus, source.latentChargeBonus + latent.chargeOnCrit.perHit);
        }
        if (latent.critDmgGrowth && resolution.critCount > 0) {
            source.latentCritDmgBonus = Math.min(latent.critDmgGrowth.maxBonus, source.latentCritDmgBonus + latent.critDmgGrowth.perCrit * resolution.critCount);
        }
        if (latent.oneShotMitigate)
            source.latentOneShotMitigate = latent.oneShotMitigate;
        // 条件と内部クールタイムは**1スキル使用につき1回**だけ見る。多段でも増えない
        if (!this.latentConditionMet(latent, source, target, resolution))
            return;
        if (latent.internalCooldown && source.latentCooldown > 0)
            return;
        if (latent.internalCooldown && (latent.runtimeEffects?.length ?? 0) > 0)
            source.latentCooldown = latent.internalCooldown;
        for (const effect of latent.runtimeEffects ?? []) {
            if (effect.kind === "SELF_GAUGE") {
                this.gainGauge(source, effect.value);
                announce();
            }
            else if (effect.kind === "SELF_HEAL") {
                const amount = Math.round(source.maxHp * effect.value);
                applyHeal(source, amount);
                this.pushEvent({ targetId: source.instanceId, kind: "HEAL", amount });
                announce();
            }
            else if (effect.kind === "LIFESTEAL") {
                if (resolution.damageDealt > 0) {
                    const amount = Math.round(resolution.damageDealt * effect.value);
                    applyHeal(source, amount);
                    this.pushEvent({ targetId: source.instanceId, kind: "HEAL", amount });
                    announce();
                }
            }
            else if (effect.kind === "SELF_CLEANSE") {
                if (cleanseDebuffs(source, effect.count) > 0)
                    announce();
            }
            else if (effect.kind === "SELF_SHIELD") {
                source.shieldValue = Math.max(source.shieldValue, Math.round(source.maxHp * effect.value));
                source.shieldTurns = Math.max(source.shieldTurns, effect.duration);
                announce();
            }
            else if (effect.kind === "LOWEST_ALLY_HEAL") {
                const amount = Math.round(lowestAlly.maxHp * effect.value);
                applyHeal(lowestAlly, amount);
                this.pushEvent({ targetId: lowestAlly.instanceId, kind: "HEAL", amount });
                announce();
            }
            else if (effect.kind === "LOWEST_ALLY_GAUGE") {
                const extra = effect.whenAllyHpBelow !== undefined && hpRatio(lowestAlly) <= effect.whenAllyHpBelow ? (effect.extra ?? 0) : 0;
                this.gainGauge(lowestAlly, effect.value + extra);
                announce();
            }
            else if (effect.kind === "LOWEST_ALLY_CLEANSE") {
                if (cleanseDebuffs(lowestAlly, effect.count) > 0)
                    announce();
            }
            else if (effect.kind === "LOWEST_ALLY_SHIELD") {
                if (!hasStatus(lowestAlly, "BUFF_BLOCK")) {
                    lowestAlly.shieldValue = Math.max(lowestAlly.shieldValue, Math.round(source.maxHp * effect.value));
                    lowestAlly.shieldTurns = Math.max(lowestAlly.shieldTurns, effect.duration);
                    announce();
                }
            }
            else if (effect.kind === "LOWEST_ALLY_MITIGATE") {
                lowestAlly.mitigateAmount = Math.max(lowestAlly.mitigateAmount, effect.value);
                lowestAlly.mitigateTurns = Math.max(lowestAlly.mitigateTurns, effect.duration);
                announce();
            }
            else if (effect.kind === "LOWEST_ALLY_BUFF") {
                if (!hasStatus(lowestAlly, "BUFF_BLOCK")) {
                    applyStatEffect(lowestAlly, effect.stat, effect.amount, effect.duration, "BUFF");
                    announce();
                }
            }
            else if (effect.kind === "ALLY_HEAL") {
                for (const ally of allies) {
                    const amount = Math.round(ally.maxHp * effect.value);
                    applyHeal(ally, amount);
                    this.pushEvent({ targetId: ally.instanceId, kind: "HEAL", amount });
                }
                announce();
            }
            else if (effect.kind === "GAUGE_DRAIN_SHARE") {
                if (resolution.gaugeRemoved > 0) {
                    this.gainGauge(source, resolution.gaugeRemoved * effect.value);
                    announce();
                }
            }
            else if (effect.kind === "STEAL_BUFF") {
                if (receiver.alive && stealBuffs(receiver, source, effect.count) > 0)
                    announce();
            }
            else if (effect.kind === "STRIP") {
                if (receiver.alive && this.rollEffectSuccess(source, receiver, effect.chance) && stripBuffs(receiver, effect.count))
                    announce();
            }
            else if (effect.kind === "GAUGE_DOWN") {
                if (receiver.alive && this.rng() < effect.chance) {
                    receiver.gauge = Math.max(0, receiver.gauge - effect.value * ATB_THRESHOLD);
                    announce();
                }
            }
            else if (effect.kind === "DEBUFF") {
                if (!receiver.alive || this.isImmune(receiver) || !this.rollEffectSuccess(source, receiver, effect.chance))
                    continue;
                if (effect.status === "HEAL_BLOCK") {
                    receiver.healBlockTurns = Math.max(receiver.healBlockTurns, effect.duration);
                    receiver.healBlockMultiplier = 0;
                }
                // 効果量はスキルと同じ共通値。潜在から入っても強さが変わらないようにする
                else if (effect.status === "SPD_DOWN")
                    applyStatEffect(receiver, "spd", -SPD_DOWN, effect.duration, "DEBUFF");
                else if (effect.status === "ATK_DOWN")
                    applyStatEffect(receiver, "atk", -ATK_DOWN, effect.duration, "DEBUFF");
                else if (effect.status === "DEF_DOWN")
                    applyStatEffect(receiver, "def", -DEF_DOWN, effect.duration, "DEBUFF");
                else if (effect.status === "POISON") {
                    receiver.poisonStacks = Math.min(5, receiver.poisonStacks + 1);
                    receiver.poisonTurns = Math.max(receiver.poisonTurns, effect.duration);
                    receiver.poisonDamageRate = effect.value ?? .05;
                }
                else if (effect.status === "STUN")
                    receiver.stunTurns = Math.max(receiver.stunTurns, effect.duration);
                else
                    applyStatus(receiver, "BUFF_BLOCK", effect.duration, source.instanceId);
                announce();
            }
            else if (effect.kind === "ALLY_GAUGE_UP") {
                if (this.rng() < effect.chance) {
                    for (const ally of allies)
                        ally.gauge = Math.min(ATB_THRESHOLD, ally.gauge + effect.value * ATB_THRESHOLD);
                    announce();
                }
            }
            else if (effect.kind === "DEBUFF_EXTEND") {
                // **明示的な延長だけ**が残りターンへ加算する道。通常の再付与は長い方を採るだけ
                if (receiver.alive && this.rng() < effect.chance) {
                    extendEffects(receiver, effect.duration, "DEBUFF");
                    if (receiver.poisonTurns)
                        receiver.poisonTurns += effect.duration;
                    if (receiver.healBlockTurns)
                        receiver.healBlockTurns += effect.duration;
                    announce();
                }
            }
            else if (effect.kind === "HEAL_CLEANSE") {
                applyHeal(lowestAlly, Math.round(lowestAlly.maxHp * effect.value));
                cleanseDebuffs(lowestAlly, 1);
                announce();
            }
            else if (effect.kind === "REGEN" && !hasStatus(lowestAlly, "BUFF_BLOCK")) {
                lowestAlly.regenRate = Math.max(lowestAlly.regenRate, effect.value);
                lowestAlly.regenTurns = Math.max(lowestAlly.regenTurns, effect.duration);
                announce();
            }
            else if (effect.kind === "SHIELD" && !hasStatus(lowestAlly, "BUFF_BLOCK")) {
                lowestAlly.shieldValue = Math.max(lowestAlly.shieldValue, Math.round(lowestAlly.maxHp * effect.value));
                lowestAlly.shieldTurns = Math.max(lowestAlly.shieldTurns, effect.duration);
                announce();
            }
        }
        switch (latent.effectType) {
            case "DAMAGE_UP":
            case "CRIT_TRIGGER":
            case "HP_SCALING":
            case "DEF_SCALING":
            case "DEBUFF_CHANCE_UP":
                return;
            case "ADD_DEBUFF": {
                if (!receiver.alive || this.isImmune(receiver))
                    return;
                // 正式な基礎発動率→命中/抵抗の共通経路を必ず使う。
                if (!this.rollEffectSuccess(source, receiver, latent.chance))
                    return;
                if (latent.status === "SPD_DOWN" || latent.status === "ATK_DOWN" || latent.status === "DEF_DOWN") {
                    // **以前はどれも -0.3 だった。**攻撃DOWNも防御DOWNも速度DOWNの量で入っていたので、
                    // 種類ごとの共通値へ直した
                    const stat = latent.status === "SPD_DOWN" ? "spd" : latent.status === "ATK_DOWN" ? "atk" : "def";
                    const amount = stat === "spd" ? SPD_DOWN : stat === "atk" ? ATK_DOWN : DEF_DOWN;
                    applyStatEffect(receiver, stat, -amount, latent.duration, "DEBUFF");
                }
                else if (latent.status === "HEAL_BLOCK") {
                    receiver.healBlockTurns = Math.max(receiver.healBlockTurns, latent.duration);
                    receiver.healBlockMultiplier = 0;
                }
                else if (latent.status === "BLIND") {
                    receiver.blindTurns = Math.max(receiver.blindTurns, latent.duration);
                }
                else if (latent.status && latent.status in STATUS_EFFECT_CATEGORY) {
                    applyStatus(receiver, latent.status, latent.duration, source.instanceId);
                }
                else
                    return;
                announce();
                return;
            }
            case "TURN_METER_DOWN":
                if (receiver.alive && proc()) {
                    receiver.gauge = Math.max(0, receiver.gauge - latent.value * ATB_THRESHOLD);
                    announce();
                }
                return;
            case "SELF_HEAL":
            case "ALLY_SUPPORT": {
                if (latent.resolution === "ON_CRIT" && !anyCrit)
                    return;
                if (latent.effectType === "ALLY_SUPPORT" && latent.resolution === "ON_CRIT") {
                    receiver.gauge += latent.value * ATB_THRESHOLD;
                }
                else {
                    applyHeal(receiver, Math.round(receiver.maxHp * latent.value));
                }
                announce();
                return;
            }
            case "SHIELD":
                if (!hasStatus(receiver, "BUFF_BLOCK")) {
                    receiver.shieldValue = Math.max(receiver.shieldValue, Math.round(receiver.maxHp * latent.value));
                    receiver.shieldTurns = Math.max(receiver.shieldTurns, latent.duration);
                    announce();
                }
                return;
            case "ADD_BUFF": {
                const onceKey = `${source.instanceId}:${latent.id}`;
                if (latent.resolution === "CONDITIONAL" && (hpRatio(source) > 0.3 || this.consumedLatents.has(onceKey)))
                    return;
                if (!latent.status || !(latent.status in STATUS_EFFECT_CATEGORY))
                    return;
                if (applyStatus(receiver, latent.status, latent.duration, source.instanceId)) {
                    if (latent.resolution === "CONDITIONAL")
                        this.consumedLatents.add(onceKey);
                    announce();
                }
                return;
            }
            case "SPECIAL_TRIGGER":
                if ((latent.resolution === "ON_CRIT" && anyCrit) || (latent.resolution === "CONDITIONAL" && debuffApplied)) {
                    source.gauge += latent.value * ATB_THRESHOLD;
                    announce();
                }
                return;
        }
    }
    /** 火傷している場合、手番の最後(行動の有無・スタンの有無を問わず)に自分の攻撃力分のダメージを受ける */
    applyBurnAtTurnEnd(unit) {
        if (unit.burnTurns <= 0 || !unit.alive)
            return;
        unit.burnTurns -= 1;
        const burnDamage = Math.max(1, Math.round(getEffectiveStat(unit, "atk")));
        applyDamage(unit, burnDamage);
        if (this.isTower70Boss(unit))
            this.afterTower70BossHpChanged(unit);
        this.push(`  → ${this.label(unit)} は火傷でダメージを受けた！ ${burnDamage} (残りHP ${unit.currentHp}/${unit.maxHp})`);
        this.pushEvent({ targetId: unit.instanceId, kind: "DAMAGE", amount: burnDamage });
        if (!unit.alive) {
            this.push(`  → ${this.label(unit)} は倒れた！`);
            this.pushEvent({ targetId: unit.instanceId, kind: "DEATH" });
        }
    }
    /** 継続回復がかかっている場合、手番開始時に最大HPのregenRate分回復する */
    applyRegenAtTurnStart(unit) {
        if (unit.regenTurns <= 0 || !unit.alive)
            return;
        const savedRate = unit.regenRate;
        unit.regenTurns -= 1;
        if (unit.regenTurns <= 0)
            unit.regenRate = 0;
        const healAmount = Math.round(unit.maxHp * (unit.regenIncludesLastTurn ? savedRate : unit.regenRate));
        if (healAmount <= 0)
            return;
        applyHeal(unit, healAmount);
        this.push(`  → ${this.label(unit)} は継続回復でHPが ${healAmount} 回復！ (${unit.currentHp}/${unit.maxHp})`);
        this.pushEvent({ targetId: unit.instanceId, kind: "HEAL", amount: healAmount });
    }
    /** 毒のスタックがある場合、手番開始時にスタック数×poisonDamageRate分のダメージを受ける */
    applyPoisonAtTurnStart(unit) {
        if (unit.poisonStacks <= 0 || !unit.alive)
            return;
        unit.poisonTurns -= 1;
        const stacks = unit.poisonStacks;
        if (unit.poisonTurns <= 0) {
            unit.poisonStacks = 0;
            unit.poisonDamageRate = 0;
        }
        const poisonDamage = Math.max(1, Math.round(unit.maxHp * unit.poisonDamageRate * stacks));
        applyDamage(unit, poisonDamage);
        if (this.isTower70Boss(unit))
            this.afterTower70BossHpChanged(unit);
        this.push(`  → ${this.label(unit)} は毒(${stacks}スタック)でダメージを受けた！ ${poisonDamage} (残りHP ${unit.currentHp}/${unit.maxHp})`);
        this.pushEvent({ targetId: unit.instanceId, kind: "DAMAGE", amount: poisonDamage });
        this.onPoisonDamage(unit);
        if (!unit.alive) {
            this.push(`  → ${this.label(unit)} は倒れた！`);
            this.pushEvent({ targetId: unit.instanceId, kind: "DEATH" });
        }
    }
    /**
     * @param sourceScoped この呼び出しで「術者/味方に向いた効果」を適用してよいか。
     *   全体技では対象ごとにこの関数が呼ばれるため、最初の対象のときだけtrueになる。
     *   ライフスティールは与えたダメージに比例するので、ここには含めず毎回適用する。
     */
    applySkillEffects(source, target, skill, missed = false, sourceScoped = true, latent, resolution = newResolution(), perHit = false) {
        let damageDealtThisCall = 0;
        // 反撃は効果の解決の途中に割り込ませない(解決中に相手が動くと、
        // 残りの効果が誰に乗るのか分からなくなる)。数えておいて最後にまとめて返す
        const counterTargets = new Set();
        if (!resolution.targetHpBefore.has(target.instanceId)) {
            resolution.targetHpBefore.set(target.instanceId, target.currentHp / target.maxHp);
        }
        /*
         * **この相手から強化効果を剥がせたか。**`resolution` ではなくここに置く。
         *
         * `resolution` は1回の技で相手全員ぶんを通して共有されるので、
         * そちらに持たせると**1体から剥がせただけで全員に強化不可が付く。**
         * 「解除に成功した相手にだけ」は相手ごとの話なので、相手ごとの変数で持つ。
         */
        let strippedThisTarget = false;
        /** 解決の途中の結果まで含めて、条件が満たされているかを見る */
        const met = (condition) => {
            if (!condition)
                return true;
            if (condition === "STRIPPED_TARGET")
                return strippedThisTarget;
            if (condition === "ANY_CRIT")
                return resolution.critCount >= 1;
            if (condition === "CRITS_AT_LEAST_2")
                return resolution.critCount >= 2;
            if (condition === "CRITS_AT_LEAST_3")
                return resolution.critCount >= 3;
            if (condition === "STUN_FAILED")
                return resolution.stunFailed;
            if (condition === "KILLED_TARGET")
                return resolution.kills > 0;
            return evaluateTargetCondition(condition, source, target);
        };
        for (const effect of skill.effects) {
            /*
             * 倒れた相手には、それ以上の効果を乗せない。
             *
             * **拡散(SPLASH)はここで止めない。**止めると、メイン対象を倒した時だけ
             * 周りへ広がらなくなる——**いちばん強く当たった時に拡散しない**という、
             * 技の趣旨と正反対のことが起きる(実際にそうなっていた)。
             * 拡散が見るのは「その相手へ実際に与えた量」で、相手の生死ではない。
             */
            if (!target.alive && effect.kind !== "HEAL" && effect.kind !== "LIFESTEAL"
                && effect.kind !== "SPLASH" && !isSourceScopedEffect(effect))
                continue;
            // 暗闇で外した場合、ダメージ以外の効果は一切乗らない
            if (missed && effect.kind !== "DAMAGE" && effect.kind !== "LIFESTEAL")
                continue;
            if (!sourceScoped && isSourceScopedEffect(effect))
                continue;
            if ('requires' in effect && !met(effect.requires))
                continue;
            switch (effect.kind) {
                case "CURSE": {
                    if (!this.isImmune(target) && this.rollEffectSuccess(source, target, effect.chance))
                        this.addCurse(source, target);
                    break;
                }
                case "DETONATE_CURSES":
                    this.detonateCurses(target, true);
                    break;
                case "CONVERT_CURSES": {
                    // 1対象につき1回の成功判定。免疫を含む強化を剥がしてから呪いへ変える。
                    if (!this.rollEffectSuccess(source, target, effect.chance))
                        break;
                    const removed = stripBuffs(target);
                    if (!this.isImmune(target)) {
                        for (let i = 0; i < removed; i++)
                            this.addCurse(source, target);
                        if (removed > 0)
                            target.stunTurns = Math.max(target.stunTurns, 1);
                    }
                    break;
                }
                case "DAMAGE_BOOST": {
                    for (const receiver of this.receiversFor(source, target, effect.applyTo)) {
                        if (!receiver.alive || hasStatus(receiver, "BUFF_BLOCK"))
                            continue;
                        receiver.damageDealtBonus = Math.max(receiver.damageDealtBonus ?? 0, effect.amount);
                        receiver.damageDealtBonusTurns = Math.max(receiver.damageDealtBonusTurns ?? 0, effect.durationTurns);
                    }
                    break;
                }
                case "DAMAGE": {
                    if (!met(effect.requires))
                        break;
                    // 「奪った強化1個につき」は解決の途中の結果を見るので、ここで足してから撃つ
                    const stolenBonus = effect.stolenBuffBonus
                        ? Math.min(effect.stolenBuffBonus.maxBonus, resolution.stolenBuffs * effect.stolenBuffBonus.perBuff)
                        : 0;
                    const damageEffect = stolenBonus > 0
                        ? { ...effect, finalDamageBonus: (effect.finalDamageBonus ?? 0) + stolenBonus }
                        : effect;
                    const hits = effect.hits ?? 1;
                    for (let h = 0; h < hits && target.alive; h += 1) {
                        const cheat = passiveEffectOf(source);
                        const enhanced = cheat?.kind === "CHEAT" ? { ...damageEffect, hpCoefficient: (damageEffect.hpCoefficient ?? 0) + .07 / hits } : damageEffect;
                        const result = calcDamage(source, target, enhanced, this.rng);
                        if (result.isGlancing)
                            resolution.glancedTargets.add(target.instanceId);
                        if (result.isCrit) {
                            resolution.anyCrit = true;
                            resolution.critCount += 1;
                            // 「各ヒットのクリティカルで」と明記された技だけ、ヒットごとに得る
                            if (effect.gaugeOnCritPerHit)
                                this.gainGauge(source, effect.gaugeOnCritPerHit);
                        }
                        if (result.isCrit && latent?.effectType === "CRIT_TRIGGER")
                            result.damage = Math.round(result.damage * (1 + latent.value));
                        // 暗闇で外した攻撃はかすり傷程度にしかならない
                        if (missed)
                            result.damage = Math.max(1, Math.round(result.damage * (1 - BLIND_DAMAGE_REDUCTION)));
                        const applied = this.applyIncomingDamage(target, result.damage, source, "normal", resolution);
                        damageDealtThisCall += applied.hpDamage;
                        resolution.damageDealt += applied.hpDamage;
                        if (applied.died) {
                            resolution.kills += 1;
                            this.onKill(source);
                        }
                        if (result.isCrit && target.alive && passiveEffectOf(target)?.kind === "CHEAT") {
                            const key = `cheat:${target.instanceId}`;
                            if (!resolution.applied.has(key)) {
                                resolution.applied.add(key);
                                this.pushPassiveCue(target);
                                const before = target.currentHp;
                                applyHeal(target, Math.round(target.maxHp * .1));
                                this.pushEvent({ targetId: target.instanceId, kind: "HEAL", amount: target.currentHp - before });
                            }
                        }
                        if (effect.perHitEffects && target.alive && !missed)
                            this.applySkillEffects(source, target, { ...skill, effects: effect.perHitEffects }, false, false, undefined, resolution, true);
                        target.hitsTaken += 1;
                        this.advanceAdaptation(target, source);
                        counterTargets.add(target);
                        const critText = result.isCrit ? "会心の一撃！" : "";
                        const affinityText = result.isGlancing
                            ? " かすった！"
                            : result.affinity === "ADVANTAGE" ? " 効果は抜群だ！" : result.affinity === "DISADVANTAGE" ? " 効果は今ひとつだ…" : "";
                        this.push(`  → ${this.label(target)} に ${applied.hpDamage} ダメージ！${critText}${affinityText} (残りHP ${target.currentHp}/${target.maxHp})`);
                        this.pushEvent({ targetId: target.instanceId, kind: "DAMAGE", amount: applied.hpDamage, isCrit: result.isCrit });
                    }
                    break;
                }
                case "SPLASH": {
                    /*
                     * 拡散。**メイン対象へ実際に削った量**を、対象以外の敵へ配る。
                     *
                     * `damageDealtThisCall` は、この呼び出しでこの相手のHPを削った合計。
                     * 会心も属性相性も相手の防御も通り抜けた後の数字なので、
                     * **本命を通すほど周りへの被害も増える。**
                     *
                     * **`applyIncomingDamage` を直に呼ぶ。**DAMAGE効果を通さないので、
                     * ここからさらに拡散が生えることも、スキルの他の効果(弱体・ゲージ)が
                     * 敵の数だけ再発動することもない。拡散は「ダメージだけが広がる」もの。
                     *
                     * `sourceScoped` を見るのは念のため。S1は単体技なので解決は1回しか
                     * 走らないが、**将来この効果を全体技へ載せた人が、対象の数だけ
                     * 拡散を撒いてしまわないように**最初の1回に限っておく。
                     */
                    if (!sourceScoped || damageDealtThisCall <= 0)
                        break;
                    const ratio = Math.max(0, effect.ratio + (latent?.splashRatioBonus ?? 0));
                    if (ratio <= 0)
                        break;
                    const amount = Math.max(1, Math.round(damageDealtThisCall * ratio));
                    const others = this.units.filter((unit) => unit.alive && unit.team !== source.team && unit !== target);
                    if (others.length === 0)
                        break;
                    this.push(`  → 光が弾けて広がった！(${Math.round(ratio * 100)}%)`);
                    for (const other of others) {
                        const applied = this.applyIncomingDamage(other, amount, source, "normal", resolution);
                        resolution.damageDealt += applied.hpDamage;
                        if (applied.died) {
                            resolution.kills += 1;
                            this.onKill(source);
                        }
                        this.push(`  → ${this.label(other)} に ${applied.hpDamage} ダメージ！ (残りHP ${other.currentHp}/${other.maxHp})`);
                        this.pushEvent({ targetId: other.instanceId, kind: "DAMAGE", amount: applied.hpDamage });
                    }
                    break;
                }
                case "HEAL": {
                    // 回復先はスキルの対象とは限らない。敵を殴りながら味方を癒す技がある
                    const receivers = this.receiversFor(source, target, effect.applyTo);
                    for (const receiver of receivers) {
                        if (!receiver.alive)
                            continue;
                        const healBase = effect.scaleStat === "atk"
                            ? getEffectiveStat(source, "atk")
                            : effect.scaleStat === "def"
                                ? getEffectiveStat(source, "def")
                                : effect.scaleStat === "hp" ? source.maxHp : receiver.maxHp;
                        /*
                         * 才能の回復補正。**術者側の才能だけを見る。**
                         * 受け手の「回復量+」で自分への回復が増えると、
                         * 回復役を育てる意味が薄れて全員に薄く配るのが最適になる。
                         */
                        const healBoost = source.def.combatMods?.healingMultiplier ?? 1;
                        // 緊急回復。受け手が落ちかけている時だけ乗る
                        const lowHp = effect.lowHpExtra && hpRatio(receiver) <= effect.lowHpExtra.hpRatio
                            ? effect.lowHpExtra.extra : 0;
                        const healAmount = Math.round(healBase * effect.healRate * healBoost * (1 + lowHp));
                        if (healAmount <= 0)
                            continue;
                        applyHeal(receiver, healAmount);
                        this.push(`  → ${this.label(receiver)} のHPが ${healAmount} 回復！ (${receiver.currentHp}/${receiver.maxHp})`);
                        this.pushEvent({ targetId: receiver.instanceId, kind: "HEAL", amount: healAmount });
                        /*
                         * 波及治療。**単体回復の時だけ**、他の味方にも薄く配る。
                         * 全体回復に付けても意味が無く、
                         * 「1体に絞った代わりに広がる」という取引がこの覚醒の中身。
                         */
                        const splash = skill.talentMods?.healSplash;
                        if (splash && receivers.length === 1) {
                            const amount = Math.round(healAmount * splash);
                            for (const ally of this.units) {
                                if (!ally.alive || ally.team !== source.team || ally === receiver || amount <= 0)
                                    continue;
                                applyHeal(ally, amount);
                                this.pushEvent({ targetId: ally.instanceId, kind: "HEAL", amount });
                            }
                            if (amount > 0)
                                this.push(`  → 回復が味方全体へ波及した！ (${amount})`);
                        }
                    }
                    break;
                }
                case "LIFESTEAL": {
                    if (!source.alive || damageDealtThisCall <= 0)
                        break;
                    const lowExtra = effect.selfLowHpExtra && hpRatio(source) <= effect.selfLowHpExtra.hpRatio
                        ? effect.selfLowHpExtra.extra
                        : 0;
                    const healAmount = Math.min(Math.round(damageDealtThisCall * (effect.healRate + lowExtra)), effect.maxSourceHpRate === undefined ? Infinity : Math.floor(source.maxHp * effect.maxSourceHpRate));
                    if (healAmount <= 0)
                        break;
                    applyHeal(source, healAmount);
                    this.push(`  → ${this.label(source)} は与えたダメージの一部でHPが ${healAmount} 回復！ (${source.currentHp}/${source.maxHp})`);
                    this.pushEvent({ targetId: source.instanceId, kind: "HEAL", amount: healAmount });
                    break;
                }
                case "BUFF": {
                    // 強化効率・延長支援。どちらも**その効果1つにつき1回**だけ判定する
                    const buffTurns = effect.durationTurns + this.talentExtend(skill, "buff");
                    const buffAmount = effect.amount;
                    // 適用先を選べる。敵を攻撃しつつ味方を強化するスキルなどで使う
                    const receivers = this.receiversFor(source, target, effect.applyTo);
                    for (const receiver of receivers) {
                        if (hasStatus(receiver, "BUFF_BLOCK")) {
                            this.push(`  → ${this.label(receiver)} は強化不可でBUFF付与を防いだ！`);
                            continue;
                        }
                        // 同じ能力の強化は重ねない。すでに付いていれば長い方のターンを採る
                        applyStatEffect(receiver, effect.stat, buffAmount, buffTurns, "BUFF");
                        this.push(`  → ${this.label(receiver)} の ${effect.stat.toUpperCase()} が上昇！ (${buffTurns}ターン)`);
                    }
                    /*
                     * 高揚支援。**強化を配った相手の与ダメージを上げる。**
                     * 強化そのものではなく「強化された状態」に乗るので、
                     * 誰に配ったかがそのまま火力の伸びになる。
                     */
                    const elation = skill.talentMods?.buffedAllyDamage;
                    if (elation && sourceScoped) {
                        for (const ally of this.units) {
                            if (!ally.alive || ally.team !== source.team || !hasAnyBuff(ally))
                                continue;
                            ally.damageDealtBonusTurns = Math.max(ally.damageDealtBonusTurns ?? 0, elation.turns);
                            ally.damageDealtBonus = Math.max(ally.damageDealtBonus ?? 0, elation.value);
                        }
                        this.push(`  → 強化された味方の与ダメージが上がった！ (高揚支援)`);
                    }
                    break;
                }
                case "DEBUFF": {
                    if (this.isImmune(target))
                        break;
                    if (!this.rollEffectSuccess(source, target, effect.chance, effect.chanceGroup, resolution, skill))
                        break;
                    // 弱化延長。**確率は効果ごとではなく、その効果1つにつき1回**振る
                    const debuffTurns = effect.durationTurns + this.talentExtend(skill, "debuff");
                    // 同じ能力の弱体は重ねない。すでに付いていれば長い方のターンを採る
                    applyStatEffect(target, effect.stat, -effect.amount, debuffTurns, "DEBUFF");
                    resolution.debuffApplied = true;
                    resolution.applied.add(`${effect.stat.toUpperCase()}_DOWN`);
                    this.push(`  → ${this.label(target)} の ${effect.stat.toUpperCase()} が低下！ (${debuffTurns}ターン)`);
                    break;
                }
                case "STATUS": {
                    if (!met(effect.requires))
                        break;
                    const category = STATUS_EFFECT_CATEGORY[effect.status];
                    const receivers = this.receiversFor(source, target, effect.applyTo);
                    for (const receiver of receivers) {
                        if (category === "DEBUFF") {
                            if (this.isImmune(receiver) || !this.rollEffectSuccess(source, receiver, effect.chance, undefined, undefined, skill))
                                continue;
                        }
                        if (!applyStatus(receiver, effect.status, effect.durationTurns, source.instanceId)) {
                            this.push(`  → ${this.label(receiver)} は強化不可でBUFF付与を防いだ！`);
                            continue;
                        }
                        this.push(`  → ${this.label(receiver)} は${STATUS_EFFECT_JA[effect.status]}を得た！ (${effect.durationTurns}ターン)`);
                        if (category === "DEBUFF") {
                            resolution.debuffApplied = true;
                            resolution.applied.add(effect.status);
                        }
                    }
                    break;
                }
                case "STUN": {
                    if (!met(effect.requires))
                        break;
                    if (this.isImmune(target) || !this.rollEffectSuccess(source, target, effect.chance, undefined, undefined, skill)) {
                        // 「スタンが失敗したら代わりにゲージを削る」型の技のために、外れたことを覚えておく
                        resolution.stunFailed = true;
                        break;
                    }
                    target.stunTurns = Math.max(target.stunTurns, effect.durationTurns);
                    resolution.debuffApplied = true;
                    resolution.applied.add("STUN");
                    this.push(`  → ${this.label(target)} はスタンした！`);
                    break;
                }
                case "BURN": {
                    if (this.isImmune(target))
                        break;
                    if (!this.rollEffectSuccess(source, target, effect.chance, undefined, undefined, skill))
                        break;
                    target.burnTurns = Math.max(target.burnTurns, effect.durationTurns);
                    resolution.debuffApplied = true;
                    resolution.applied.add("BURN");
                    this.push(`  → ${this.label(target)} は火傷を負った！ (${effect.durationTurns}ターン)`);
                    break;
                }
                case "GAUGE": {
                    if (!met(effect.requires))
                        break;
                    if (effect.chance !== undefined && this.rng() >= effect.chance)
                        break;
                    const receivers = this.receiversFor(source, target, effect.applyTo);
                    for (const receiver of receivers) {
                        if (!receiver.alive)
                            continue;
                        let amount = effect.amount;
                        if (effect.conditionalExtra && met(effect.conditionalExtra.when))
                            amount += effect.conditionalExtra.amount;
                        if (effect.lowHpExtra && hpRatio(receiver) <= effect.lowHpExtra.hpRatio)
                            amount += effect.lowHpExtra.amount;
                        /*
                         * 戦闘才能の「ゲージ増加量」。**味方を進める時だけ**乗せる。
                         * 敵を下げる側にも掛けると、支援役の才能が妨害にも効いてしまう。
                         */
                        if (amount > 0 && receiver.team === source.team) {
                            amount *= source.def.combatMods?.gaugeUpMultiplier ?? 1;
                        }
                        if (effect.drain) {
                            // 吸収: 対象から減らした分をそのまま術者へ移す
                            resolution.gaugeRemoved += this.drainGauge(source, receiver, amount);
                            this.push(`  → ${this.label(source)} が ${this.label(receiver)} の行動ゲージを吸収した！`);
                            continue;
                        }
                        const before = receiver.gauge;
                        receiver.gauge = Math.max(0, Math.min(ATB_THRESHOLD, receiver.gauge + amount * ATB_THRESHOLD));
                        if (amount < 0) {
                            const removed = (before - receiver.gauge) / ATB_THRESHOLD;
                            resolution.gaugeRemoved += removed;
                            /*
                             * 奪取。**減らした分の一部を術者が受け取る。**
                             * `drain` との違いは「減らす量そのものは変わらない」こと——
                             * 相手を止める効き目は同じまま、こちらの手番が少し増える。
                             */
                            const share = skill.talentMods?.gaugeDrainShare;
                            if (share && removed > 0)
                                this.gainGauge(source, removed * share);
                        }
                        const verb = amount >= 0 ? "進んだ" : "後退した";
                        this.push(`  → ${this.label(receiver)} の行動ゲージが${verb}！`);
                    }
                    /*
                     * 支援連鎖。**受け取っていない味方のうち、いちばん遅れている1体**へも配る。
                     * 単体加速の技でも編成全体が回るようにするための才能。
                     */
                    const chain = skill.talentMods?.gaugeChain;
                    if (chain && effect.amount > 0 && sourceScoped) {
                        const given = new Set(receivers.map((r) => r.instanceId));
                        const rest = this.units
                            .filter((u) => u.alive && u.team === source.team && !given.has(u.instanceId))
                            .sort((a, b) => a.gauge - b.gauge)[0];
                        if (rest) {
                            this.gainGauge(rest, chain);
                            this.push(`  → ${this.label(rest)} の行動ゲージも進んだ！ (支援連鎖)`);
                        }
                    }
                    break;
                }
                case "BLIND": {
                    if (this.isImmune(target))
                        break;
                    if (!this.rollEffectSuccess(source, target, effect.chance, undefined, undefined, skill))
                        break;
                    target.blindTurns = Math.max(target.blindTurns, effect.durationTurns);
                    resolution.debuffApplied = true;
                    resolution.applied.add("BLIND");
                    this.push(`  → ${this.label(target)} は暗闇に包まれた！ (${effect.durationTurns}ターン)`);
                    break;
                }
                case "SHIELD": {
                    const receivers = this.receiversFor(source, target, effect.applyTo);
                    for (const receiver of receivers) {
                        if (!receiver.alive)
                            continue;
                        if (hasStatus(receiver, "BUFF_BLOCK")) {
                            this.push(`  → ${this.label(receiver)} は強化不可でBUFF付与を防いだ！`);
                            continue;
                        }
                        // タンクの守りは「自分の頑丈さを配る」形。基準を術者のHPに切り替えられる
                        const base = effect.fromSourceHp ? source.maxHp : receiver.maxHp;
                        // 才能のシールド補正も、回復と同じく**張る側**の才能だけを見る
                        const shieldBoost = source.def.combatMods?.shieldMultiplier ?? 1;
                        const shieldAmount = Math.round(base * effect.shieldRate * shieldBoost);
                        /*
                         * スキル才能の「長期障壁」。確率で1ターン延びる。
                         * 判定は**張るたびに1回**で、受け手ごとには振らない
                         * (全体シールドで1人だけ長く残ると、盤面が読めなくなる)。
                         */
                        const mods = skill.talentMods;
                        const extend = mods?.shieldExtendChance && this.rng() < mods.shieldExtendChance ? 1 : 0;
                        receiver.shieldValue = Math.max(receiver.shieldValue, shieldAmount);
                        receiver.shieldTurns = Math.max(receiver.shieldTurns, effect.durationTurns + extend);
                        if (mods?.shieldMitigate) {
                            receiver.shieldMitigate = Math.max(receiver.shieldMitigate ?? 0, mods.shieldMitigate);
                        }
                        if (mods?.shieldReflect) {
                            receiver.shieldReflect = Math.max(receiver.shieldReflect ?? 0, mods.shieldReflect);
                        }
                        // 治癒障壁。盾を張りながら削れた分も戻す
                        if (mods?.shieldHeal) {
                            const healed = Math.round(receiver.maxHp * mods.shieldHeal);
                            if (healed > 0) {
                                applyHeal(receiver, healed);
                                this.push(`  → ${this.label(receiver)} のHPが ${healed} 回復！ (治癒障壁)`);
                            }
                        }
                        this.push(`  → ${this.label(receiver)} にシールドが張られた！ (${shieldAmount}、${effect.durationTurns + extend}ターン)`);
                    }
                    break;
                }
                case "IMMUNITY": {
                    if (!target.alive)
                        break;
                    if (hasStatus(target, "BUFF_BLOCK")) {
                        this.push(`  → ${this.label(target)} は強化不可でBUFF付与を防いだ！`);
                        break;
                    }
                    target.immuneTurns = Math.max(target.immuneTurns, effect.durationTurns);
                    this.push(`  → ${this.label(target)} は状態異常免疫を得た！ (${effect.durationTurns}ターン)`);
                    break;
                }
                case "REGEN": {
                    const receivers = this.receiversFor(source, target, effect.applyTo);
                    for (const receiver of receivers) {
                        if (!receiver.alive)
                            continue;
                        if (hasStatus(receiver, "BUFF_BLOCK")) {
                            this.push(`  → ${this.label(receiver)} は強化不可でBUFF付与を防いだ！`);
                            continue;
                        }
                        receiver.regenIncludesLastTurn = receiver.regenIncludesLastTurn || Boolean(skill.levelOverrides);
                        receiver.regenRate = Math.max(receiver.regenRate, effect.healRate);
                        receiver.regenTurns = Math.max(receiver.regenTurns, effect.durationTurns);
                        this.push(`  → ${this.label(receiver)} は継続回復を得た！ (${effect.durationTurns}ターン)`);
                    }
                    break;
                }
                case "CLEANSE": {
                    const receivers = this.receiversFor(source, target, effect.applyTo);
                    for (const receiver of receivers) {
                        if (!receiver.alive)
                            continue;
                        if (cleanseDebuffs(receiver, effect.count ?? Number.POSITIVE_INFINITY) > 0) {
                            this.push(`  → ${this.label(receiver)} のデバフが解除された！`);
                        }
                    }
                    break;
                }
                case "STRIP": {
                    // IMMUNITY自身はBUFF。対抗手段である強化解除を免疫で封じない。
                    if (!this.rollEffectSuccess(source, target, effect.chance, effect.chanceGroup, resolution, skill))
                        break;
                    const removed = stripBuffs(target, effect.count ?? Number.POSITIVE_INFINITY);
                    if (removed > 0) {
                        strippedThisTarget = true;
                        resolution.strippedTargets += 1;
                        resolution.applied.add("STRIP");
                        this.push(`  → ${this.label(target)} の有利な効果が剥がされた！`);
                        if (effect.selfGaugePerRemoved)
                            this.gainGauge(source, effect.selfGaugePerRemoved * removed);
                    }
                    break;
                }
                case "STEAL_BUFF": {
                    if (!target.alive)
                        break;
                    if (!this.rollEffectSuccess(source, target, effect.chance, undefined, undefined, skill))
                        break;
                    const stolen = stealBuffs(target, source, effect.count ?? 1);
                    if (stolen > 0) {
                        resolution.stolenBuffs += stolen;
                        resolution.applied.add("STRIP");
                        this.push(`  → ${this.label(source)} が ${this.label(target)} の有利な効果を ${stolen}個 奪った！`);
                    }
                    break;
                }
                case "MITIGATE": {
                    const receivers = this.receiversFor(source, target, effect.applyTo);
                    /*
                     * **負の `amount` は「脆弱」**(被ダメージ増加)。
                     * `damageTakenMultiplier` が `1 - reduction` で解くので、
                     * -0.4 が入れば 1.4倍になる——が、両方を `Math.max` で丸めると
                     * `Math.max(0, -0.4)` で**脆弱が何も起きないまま素通り**する。
                     * 向きごとに「より強い方を残す」形へ分ける。
                     *
                     * 正の側は従来のまま。図鑑にも塔にも**負の MITIGATE は1件も無い**ので、
                     * ここまでの軽減の挙動は1つも変わらない(90階の脆弱刻印が最初の1件)。
                     */
                    const weaken = effect.amount < 0;
                    for (const receiver of receivers) {
                        if (!receiver.alive)
                            continue;
                        receiver.mitigateAmount = weaken
                            ? Math.min(receiver.mitigateAmount, effect.amount)
                            : Math.max(receiver.mitigateAmount, effect.amount);
                        receiver.mitigateVsTaunted = Math.max(receiver.mitigateVsTaunted, effect.vsTauntedExtra ?? 0);
                        receiver.mitigateTurns = Math.max(receiver.mitigateTurns, effect.durationTurns);
                        this.push(weaken
                            ? `  → ${this.label(receiver)} は受けるダメージが ${Math.round(-effect.amount * 100)}% 増加した！ (${effect.durationTurns}ターン)`
                            : `  → ${this.label(receiver)} は受けるダメージが軽減された！ (${effect.durationTurns}ターン)`);
                    }
                    break;
                }
                case "PROTECT": {
                    // 自分を自分でかばうことはできない。その時はHP割合が最も低い別の味方を守る
                    const others = this.units.filter((unit) => unit.team === source.team && unit.alive && unit !== source);
                    const guarded = target !== source && target.alive
                        ? target
                        : others.reduce((lowest, unit) => (!lowest || hpRatio(unit) < hpRatio(lowest) ? unit : lowest), undefined);
                    if (!guarded)
                        break;
                    guarded.protectorId = source.instanceId;
                    guarded.protectShare = effect.share;
                    guarded.protectTurns = Math.max(guarded.protectTurns, effect.durationTurns);
                    this.push(`  → ${this.label(source)} が ${this.label(guarded)} を守る構えを取った！ (${effect.durationTurns}ターン)`);
                    break;
                }
                case "COUNTER_STANCE": {
                    source.counterTurns = Math.max(source.counterTurns, effect.durationTurns);
                    source.counterMultiplier = Math.max(source.counterMultiplier, effect.multiplier);
                    source.counterHpCoefficient = Math.max(source.counterHpCoefficient, effect.hpCoefficient ?? 0);
                    source.counterHealRate = Math.max(source.counterHealRate, effect.healRate ?? 0);
                    this.push(`  → ${this.label(source)} は反撃の構えを取った！ (${effect.durationTurns}ターン)`);
                    break;
                }
                case "COOLDOWN_REDUCE": {
                    if (!met(effect.requires))
                        break;
                    const receivers = this.receiversFor(source, target, effect.applyTo);
                    for (const receiver of receivers) {
                        if (!receiver.alive)
                            continue;
                        // 0未満にはしない。負に振れると「常時使える必殺技」ができてしまう
                        receiver.cooldowns = receiver.cooldowns.map((c, slot) => (effect.slot !== undefined && effect.slot !== slot ? c : Math.max(0, c - effect.turns)));
                        this.push(`  → ${this.label(receiver)} のスキルのクールタイムが ${effect.turns}ターン短縮された！`);
                    }
                    break;
                }
                case "GAUGE_ON_HIT": {
                    for (const receiver of this.receiversFor(source, target, effect.applyTo)) {
                        if (!receiver.alive)
                            continue;
                        receiver.hitGaugeAmount = Math.max(receiver.hitGaugeAmount, effect.amount);
                        receiver.hitGaugeTurns = Math.max(receiver.hitGaugeTurns, effect.durationTurns);
                        this.push(`  → ${this.label(receiver)} は攻撃を受けるたび行動ゲージが進むようになった！`);
                    }
                    break;
                }
                // 協力攻撃は対象ごとの解決ではなく、スキル全体の解決の最後で処理する
                case "COOP_ATTACK":
                    break;
                case "HEAL_BLOCK": {
                    if (this.isImmune(target))
                        break;
                    if (!this.rollEffectSuccess(source, target, effect.chance, undefined, undefined, skill))
                        break;
                    target.healBlockTurns = Math.max(target.healBlockTurns, effect.durationTurns);
                    resolution.debuffApplied = true;
                    resolution.applied.add("HEAL_BLOCK");
                    // 複数から掛かったら、いちばんきついものが残る
                    target.healBlockMultiplier = 0;
                    this.push(`  → ${this.label(target)} は治癒阻害を受けた！ (${effect.durationTurns}ターン、回復${Math.round((1 - effect.healMultiplier) * 100)}%減)`);
                    break;
                }
                case "COOLDOWN_EXTEND": {
                    if (!target.alive)
                        break;
                    // 他のデバフと同じ判定を通す。ここを素通りさせると、
                    // 状態異常無効も抵抗も効かない唯一の妨害になってしまう
                    if (this.isImmune(target))
                        break;
                    if (!this.rollEffectSuccess(source, target, effect.chance, undefined, undefined, skill))
                        break;
                    target.cooldowns = target.cooldowns.map((c) => c + effect.turns);
                    this.push(`  → ${this.label(target)} のスキルのクールタイムが ${effect.turns}ターン延長された！`);
                    break;
                }
                case "POISON": {
                    if (this.isImmune(target))
                        break;
                    if (!this.rollEffectSuccess(source, target, effect.chance, undefined, undefined, skill))
                        break;
                    // 「既に毒状態ならさらに重ねる」は、判定より先に今の状態を見る
                    const alreadyPoisoned = target.poisonStacks > 0;
                    const stacks = (effect.stacks ?? 1) + (alreadyPoisoned ? (effect.extraStacksIfPoisoned ?? 0) : 0);
                    target.poisonStacks = Math.min(5, target.poisonStacks + stacks);
                    resolution.debuffApplied = true;
                    resolution.applied.add("POISON");
                    target.poisonTurns = Math.max(target.poisonTurns, effect.durationTurns);
                    target.poisonDamageRate = Math.max(target.poisonDamageRate, effect.damageRatePerStack);
                    this.push(`  → ${this.label(target)} は毒を受けた！ (${target.poisonStacks}スタック、${effect.durationTurns}ターン)`);
                    break;
                }
            }
        }
        /*
         * 弱化が通った時の才能。**この相手に1回だけ。**
         * 効果ごとに配ると、弱体を3つ持つ技で3倍もらえてしまう。
         */
        if (perHit)
            return { anyCrit: resolution.anyCrit, debuffApplied: resolution.debuffApplied };
        const mods = skill.talentMods;
        if (mods && resolution.debuffApplied && target.alive) {
            if (mods.selfGaugeOnDebuff) {
                this.gainGauge(source, mods.selfGaugeOnDebuff, `${this.label(source)} の行動ゲージが進んだ！ (追圧)`);
            }
            if (mods.targetGaugeOnDebuff) {
                target.gauge = Math.max(0, target.gauge - mods.targetGaugeOnDebuff * ATB_THRESHOLD);
                this.push(`  → ${this.label(target)} の行動ゲージが後退した！ (ゲージ抑制)`);
            }
            /*
             * 弱化拡散。**単体技のときだけ。**全体技に付けても意味が無く、
             * 「1体に絞った代わりに広がる」という取引がこの才能の中身。
             */
            if (mods.debuffSpreadChance && skill.target === "SINGLE_ENEMY" && this.rng() < mods.debuffSpreadChance) {
                const others = this.units.filter((u) => u.alive && u.team !== source.team && u !== target);
                const pick = others[Math.floor(this.rng() * others.length)];
                const spread = target.effects.find((e) => e.kind === "DEBUFF");
                if (pick && spread && !this.isImmune(pick)) {
                    applyStatEffect(pick, spread.stat, spread.amount, spread.remainingTurns, "DEBUFF");
                    this.push(`  → ${this.label(pick)} にも弱化が広がった！ (弱化拡散)`);
                }
            }
        }
        /*
         * 攻撃が通った時のゲージ奪取。**当たった相手ごとに1回。**
         * 減らす量と得る量が同じなので、盤面全体の手番の総量は変わらない。
         */
        if (mods?.gaugeSteal && damageDealtThisCall > 0 && target.alive && this.rng() < mods.gaugeSteal.chance) {
            const moved = Math.min(target.gauge, mods.gaugeSteal.value * ATB_THRESHOLD);
            target.gauge -= moved;
            this.gainGauge(source, moved / ATB_THRESHOLD);
            this.push(`  → ${this.label(source)} が ${this.label(target)} の行動ゲージを奪った！`);
        }
        for (const victim of counterTargets)
            this.tryCounter(victim, source);
        return { anyCrit: resolution.anyCrit, debuffApplied: resolution.debuffApplied };
    }
    /** 特殊ダメージにも共通の致死処理を通し、通常由来だけ反射を1段生成する。 */
    addCurse(source, target) {
        (target.curses ??= []).push({ attack: getEffectiveStat(source, "atk"), turns: 2, sourceId: source.instanceId });
        this.push(`  → ${this.label(target)} に呪いが付与された！`);
    }
    detonateCurses(target, all) {
        const ready = (target.curses ?? []).filter(c => all || c.turns <= 0);
        target.curses = (target.curses ?? []).filter(c => !ready.includes(c));
        for (const curse of ready) {
            if (!target.alive)
                continue;
            const source = this.units.find(u => u.instanceId === curse.sourceId);
            // 固定ダメージには攻撃スキルの倍率・会心・防御・属性補正を掛けない。
            const hit = this.applyIncomingDamage(target, Math.round(curse.attack * 4), source, "periodic");
            this.push(`  → ${this.label(target)} の呪いが発動！ ${hit.hpDamage}ダメージ`);
            this.pushEvent({ targetId: target.instanceId, kind: "DAMAGE", amount: hit.hpDamage });
            if (hit.died) {
                this.onKill(source);
                this.pushEvent({ targetId: target.instanceId, kind: "DEATH" });
                if (this.resolution)
                    this.resolution.kills++;
            }
            if (target.alive && !this.isImmune(target) && source && this.rollEffectSuccess(source, target, 1))
                target.stunTurns = Math.max(target.stunTurns, 1);
        }
    }
    /**
     * 長引いた戦いでの、与えるダメージの増え方(`damageRamp`)。
     *
     * **どんな種類のダメージにも同じだけ掛ける。**通常攻撃だけを増やすと、
     * 毒や反撃で削る編成だけが決着から取り残される。
     *
     * 数えるのは**済んだ手番の数**。ここは手番の最中に呼ばれるので、
     * 進行中の1手ぶんは入っていない(1ずれるだけなので、そのまま使う)。
     */
    damageRampFactor() {
        const ramp = this.damageRamp;
        if (!ramp)
            return 1;
        const past = this.turns.length - ramp.afterTurns;
        if (past < 0)
            return 1;
        const steps = Math.floor(past / ramp.everyTurns) + 1;
        return ramp.factorPerStep ** steps;
    }
    applyIncomingDamage(target, amount, source, sourceType = "normal", resolution = null) {
        this.syncTower80Boss();
        const equipmentMultiplier = Math.max(0, Math.min(1, target.def.latentAbility?.damageTakenMultiplier ?? 1));
        const hpBefore = hpRatio(target);
        // 軽減とパッシブによる被ダメージ減は、無敵・シールドより手前で1度だけ掛ける
        let incoming = Math.round(amount * equipmentMultiplier * damageTakenMultiplier(target, source ? hasStatus(source, "TAUNT") : false) * this.tower80DamageTakenFactor(target) * this.damageRampFactor());
        if (target.latentOneShotMitigate > 0)
            target.latentOneShotMitigate = 0;
        /*
         * 防御障壁。**盾が乗っている間だけ**の軽減で、割れたら消える。
         * シールドそのものとは別枠——「盾が残っている限り硬い」という形にすることで、
         * 盾を張り直す手番に意味が出る。
         */
        if (target.shieldMitigate && target.shieldTurns > 0 && target.shieldValue > 0) {
            incoming = Math.round(incoming * (1 - target.shieldMitigate));
        }
        /*
         * かばう。**軽減のあと、致死処理の前**に割り込む。
         * 先に肩代わりすると守る側が軽減の恩恵を受けられず、
         * 後に回すと守られた側が一度倒れてから肩代わりが起きてしまう。
         */
        const protector = target.protectTurns > 0
            ? this.units.find((unit) => unit.instanceId === target.protectorId && unit.alive)
            : undefined;
        if (protector && protector !== target && sourceType === "normal" && incoming > 0) {
            const shared = Math.round(incoming * target.protectShare);
            if (shared > 0) {
                incoming -= shared;
                const taken = applyDamage(protector, Math.round(shared * damageTakenMultiplier(protector)));
                this.push(`  → ${this.label(protector)} が ${this.label(target)} をかばった！ ${taken.hpDamage} ダメージ (残りHP ${protector.currentHp}/${protector.maxHp})`);
                this.pushEvent({ targetId: protector.instanceId, kind: "DAMAGE", amount: taken.hpDamage });
                if (taken.died) {
                    this.push(`  → ${this.label(protector)} は倒れた！`);
                    this.pushEvent({ targetId: protector.instanceId, kind: "DEATH" });
                }
            }
        }
        const illusion = passiveEffectOf(target);
        if (illusion?.kind === "ILLUSION" && source && ["LIGHT", "DARK"].includes(source.def.element))
            incoming = Math.round(incoming * .5);
        const applied = applyDamage(target, incoming);
        /*
         * 反射障壁。**盾が乗っている間だけ**、受けたぶんの一部を返す。
         * 反射で反射を呼ばないよう、返す一撃は "reflect" として扱う
         * (既存の REFLECT 状態と同じ扱い)。
         */
        if (target.shieldReflect && target.shieldTurns > 0 && sourceType === "normal"
            && source && source.alive && source.team !== target.team && applied.hpDamage > 0) {
            const back = Math.round(applied.hpDamage * target.shieldReflect);
            if (back > 0) {
                const hit = applyDamage(source, back);
                this.push(`  → ${this.label(target)} の障壁が ${hit.hpDamage} ダメージを返した！`);
                this.pushEvent({ targetId: source.instanceId, kind: "DAMAGE", amount: hit.hpDamage });
                if (hit.died) {
                    this.push(`  → ${this.label(source)} は倒れた！`);
                    this.pushEvent({ targetId: source.instanceId, kind: "DEATH" });
                }
            }
        }
        this.syncTower80Boss();
        if (this.isTower70Boss(target) && target.alive && applied.hpDamage > 0)
            this.afterTower70BossHpChanged(target);
        if (applied.invincible)
            this.push(`  → ${this.label(target)} は無敵でダメージを無効化した！`);
        if (applied.endured)
            this.push(`  → ${this.label(target)} は我慢でHP1に踏みとどまった！`);
        if (applied.revived)
            this.push(`  → ${this.label(target)} は最大HPの25%で復活した！`);
        if (applied.died) {
            this.push(`  → ${this.label(target)} は倒れた！`);
            this.pushEvent({ targetId: target.instanceId, kind: "DEATH" });
        }
        if (sourceType === "normal" && applied.hpDamage > 0) {
            this.onDamaged(target, source, resolution);
            this.tryCounterStance(target, source);
        }
        // HP閾値を「またいだ瞬間」だけ拾う。下回り続けている間ずっと出続けないようにする
        if (target.alive && hpBefore > 0.3 && hpRatio(target) <= 0.3)
            this.onAllyHpThreshold(target);
        if (sourceType === "normal" && source?.alive && applied.hpDamage > 0 && hasStatus(target, "REFLECT")) {
            const reflected = Math.round(applied.hpDamage * 0.25);
            if (reflected > 0) {
                this.push(`  → ${this.label(target)} の反射！ ${this.label(source)} へ ${reflected} ダメージ！`);
                const reflectedResult = this.applyIncomingDamage(source, reflected, target, "reflect");
                this.pushEvent({ targetId: source.instanceId, kind: "DAMAGE", amount: reflectedResult.hpDamage });
            }
        }
        return applied;
    }
    /**
     * 反撃。**手数で押す戦い方に代償を作る。**
     *
     * 小さい攻撃を何度も当てる、多段で削る、毒を重ねる——どれも手数が要る。
     * 決めた回数を受けるたびに、受けた側が即座に殴り返す。
     *
     * 反撃そのものは反撃を呼ばない(呼ぶと相討ちが無限に続く)。
     */
    /**
     * 反撃態勢による反撃。ボスの `counterAfterHits` と違い**回数を溜めずに毎回返す**。
     * 反撃そのものは反撃を呼ばない(相討ちが無限に続く)。
     */
    tryCounterStance(defender, attacker) {
        if (defender.counterTurns <= 0 || !defender.alive || !attacker?.alive)
            return;
        if (attacker.team === defender.team)
            return;
        const result = calcDamage(defender, attacker, {
            kind: "DAMAGE",
            multiplier: defender.counterMultiplier,
            hpCoefficient: defender.counterHpCoefficient > 0 ? defender.counterHpCoefficient : undefined,
        }, this.rng);
        const applied = this.applyIncomingDamage(attacker, result.damage, defender, "reflect");
        this.push(`  → ${this.label(defender)} の反撃！ ${this.label(attacker)} に ${applied.hpDamage} ダメージ (残りHP ${attacker.currentHp}/${attacker.maxHp})`);
        this.pushEvent({ targetId: attacker.instanceId, kind: "DAMAGE", amount: applied.hpDamage, isCrit: result.isCrit });
        if (defender.counterHealRate > 0) {
            const healAmount = Math.round(defender.maxHp * defender.counterHealRate);
            applyHeal(defender, healAmount);
            this.pushEvent({ targetId: defender.instanceId, kind: "HEAL", amount: healAmount });
        }
    }
    tryCounter(defender, attacker) {
        const traits = defender.def.bossTraits;
        const every = traits?.counterAfterHits ?? 0;
        if (every <= 0 || !defender.alive || !attacker.alive)
            return;
        if (defender.hitsTaken < every)
            return;
        /*
         * **反撃の中から反撃を呼ばない。**
         *
         * 反撃そのものは被弾数を増やさないので普通は連鎖しないが、
         * 反射(REFLECT)を張った相手を殴ると跳ね返りで自分の被弾数が増える。
         * そこから次の反撃が立ち上がると、盤面が動かないまま延々と往復する。
         */
        if (this.counterDepth > 0)
            return;
        defender.hitsTaken -= every;
        // 溜めた反撃で**スキルをそのまま撃つ**指定があれば、そちらへ回す
        if (traits?.counterSkillIndex !== undefined) {
            this.counterWithSkill(defender, traits.counterSkillIndex);
            return;
        }
        const result = calcDamage(defender, attacker, { kind: "DAMAGE", multiplier: traits?.counterMultiplier ?? 1.2 }, this.rng);
        applyDamage(attacker, result.damage);
        this.push(`  → ${this.label(defender)} の反撃！ ${this.label(attacker)} に ${result.damage} ダメージ (残りHP ${attacker.currentHp}/${attacker.maxHp})`);
        this.pushEvent({ targetId: attacker.instanceId, kind: "DAMAGE", amount: result.damage, isCrit: result.isCrit });
        if (!attacker.alive) {
            this.push(`  → ${this.label(attacker)} は倒れた！`);
            this.pushEvent({ targetId: attacker.instanceId, kind: "DEATH" });
        }
    }
    /**
     * 溜めた反撃で、自分のスキルをそのまま撃つ。
     *
     * ## 通常の手番と、どこが違うか
     *
     *   ・**クールタイムを動かさない。** 反撃で溜まりが消えるなら、
     *     こちらの手数がそのままボスの手を縛る道具になってしまう
     *   ・手番を消費しない(行動ゲージにも触らない)
     *   ・協力攻撃・撃破による追加ターンは呼ばない(反撃から手番が増えると、
     *     殴った側が損をする形が二重になる)
     *
     * ダメージ・会心・命中/抵抗・ゲージ吸収・解除は、**本編と同じ
     * `applySkillEffects` をそのまま通す。** ここで別式を書くと、
     * 本編を直した時にボスの反撃だけが古い規則で殴り続ける。
     */
    /**
     * 倒れた取り巻きのぶんだけ、本体を強くする。
     *
     * ## 死んだ瞬間ではなく、走査で拾う
     *
     * 死は毒でも火傷でも反撃でも起きるので、**倒れ方ごとに合図を挿していくと
     * 必ずどれか一つを取りこぼす。**代わりに手番の切れ目ごとに全員を見て、
     * まだ弔っていない死体があれば処理する。`mournedDeaths` に控えるので、
     * 同じ死で二度強くなることはない。
     *
     * 効き先は「生き残っている勝利条件の敵」だけ。取り巻き同士では強め合わない
     * (どちらを先に倒しても同じ、では順番を考える意味が無くなる)。
     */
    applyAllyDeathBoosts() {
        for (const victim of this.units) {
            if (victim.alive || this.mournedDeaths.has(victim.instanceId))
                continue;
            this.mournedDeaths.add(victim.instanceId);
            const boost = victim.def.bossTraits?.empowerBossOnDeath;
            if (!boost)
                continue;
            for (const boss of this.units) {
                if (!boss.alive || boss === victim || boss.team !== victim.team || !boss.def.victoryTarget)
                    continue;
                const parts = [];
                for (const stat of ["atk", "spd", "def"]) {
                    const amount = boost[stat];
                    if (!amount)
                        continue;
                    boss.flatStatBonus[stat] = (boss.flatStatBonus[stat] ?? 0) + amount;
                    parts.push(`${stat.toUpperCase()}+${amount}`);
                }
                /*
                 * 割合の変化。**実数では書けないものだけがここに来る。**
                 * 目覚の深域の才能晶は「防御を20%無視するようになる」
                 * 「受けるダメージが15%減る」を残していく。
                 */
                const ratio = victim.def.bossTraits?.empowerBossOnDeathRatio;
                if (ratio?.defenseIgnoreRatio) {
                    boss.deathBoostDefenseIgnore = (boss.deathBoostDefenseIgnore ?? 0) + ratio.defenseIgnoreRatio;
                    parts.push(`防御無視+${Math.round(ratio.defenseIgnoreRatio * 100)}%`);
                }
                if (ratio?.damageTakenMultiplier !== undefined) {
                    boss.deathBoostDamageTaken = (boss.deathBoostDamageTaken ?? 1) * ratio.damageTakenMultiplier;
                    parts.push(`被ダメ-${Math.round((1 - ratio.damageTakenMultiplier) * 100)}%`);
                }
                if (parts.length > 0) {
                    this.push(`${this.label(boss)} は ${this.label(victim)} の力を取り込んだ！ (${parts.join(" ")})`);
                }
            }
        }
    }
    /**
     * 才能適応を1段進める。**別の相手から受けたら1段戻す。**
     *
     * ## なぜ「戻す」を入れるのか
     *
     * 積むだけなら、答えは「もっと強い1体を作る」で終わってしまう
     * (適応が乗り切る前に落とせばいい)。**別の味方が殴れば戻る**からこそ、
     * 手を配るという別の答えが生まれる。
     * 数字ではなく編成の形を問う仕掛けにするための、いちばん大事な半分。
     *
     * 進めるのは**ヒットごと**。多段攻撃は1回で数段ぶん進むので、
     * 手数の多い技ほど早く効かなくなる——それも「同じ手の繰り返し」に含む。
     */
    advanceAdaptation(target, source) {
        const trait = target.def.bossTraits?.talentAdaptation;
        if (!trait || source.team === target.team)
            return;
        if (!target.adaptationStacks)
            target.adaptationStacks = new Map();
        const stacks = target.adaptationStacks;
        if (target.lastAttackerId && target.lastAttackerId !== source.instanceId) {
            // 別の味方が入った。**前の相手への適応が1段緩む**
            const previous = stacks.get(target.lastAttackerId) ?? 0;
            if (previous > 0)
                stacks.set(target.lastAttackerId, previous - 1);
        }
        target.lastAttackerId = source.instanceId;
        const maxStacks = Math.ceil(trait.maxReduction / trait.perStack);
        const current = stacks.get(source.instanceId) ?? 0;
        if (current >= maxStacks)
            return;
        stacks.set(source.instanceId, current + 1);
        if (current + 1 === maxStacks) {
            this.push(`  → ${this.label(target)} は ${this.label(source)} の攻撃に適応しきった！`);
        }
    }
    counterWithSkill(source, index) {
        const skill = source.def.skills[index];
        if (!skill || skill.passive)
            return;
        const targets = chooseTargets(source, skill, this.units);
        if (targets.length === 0)
            return;
        this.push(`  → ${this.label(source)} の反撃「${skill.name}」！`);
        this.counterDepth += 1;
        const resolution = newResolution();
        const previousResolution = this.resolution;
        this.resolution = resolution;
        try {
            targets.forEach((target, i) => this.applySkillEffects(source, target, skill, false, i === 0, undefined, resolution));
        }
        finally {
            this.resolution = previousResolution;
            this.counterDepth -= 1;
        }
        for (const target of new Set(targets)) {
            if (!target.alive) {
                this.push(`  → ${this.label(target)} は倒れた！`);
                this.pushEvent({ targetId: target.instanceId, kind: "DEATH" });
            }
        }
    }
    /** 状態異常免疫中かどうかを判定する。免疫中ならログを出してtrueを返す(呼び出し側はこの後の付与処理をスキップすること) */
    isImmune(target) {
        if (target.immuneTurns <= 0)
            return false;
        this.push(`  → ${this.label(target)} は状態異常免疫で無効化した！`);
        return true;
    }
    /**
     * 状態異常(デバフ・スタン・火傷)の発動判定。まずスキル自体の発動確率(chance、省略時は必ず発動を試みる)を
     * 判定し、成功したら続けて命中率/抵抗率による的中判定を行う。的中率は
     * (1 - 相手の効果抵抗率 + 自分の効果命中率) / (1 + 自分の効果命中率) で求まり、
     * 命中率を最大まで積んでも相手の抵抗率を完全には無効化できない(必ず一定の抵抗余地が残る)。
     * 的中シリーズ(4個セット)を装着していれば相手の抵抗率をさらに一部無視する。
     * 抵抗成功時、抵抗シリーズ(4個セット)を装着していればHPが回復する。
     */
    /**
     * 才能による持続の延長。**その効果1つにつき1回だけ**判定する。
     *
     * 受け手ごとに振ると、全体強化で1人だけ長く残る盤面ができて読めなくなる。
     * 確率1の覚醒(延長支援・弱化延長)は必ず+1になる。
     */
    talentExtend(skill, kind) {
        const chance = kind === "buff" ? skill.talentMods?.buffExtendChance : skill.talentMods?.debuffExtendChance;
        if (!chance)
            return 0;
        return this.rng() < chance ? 1 : 0;
    }
    rollEffectSuccess(source, target, baseChance, chanceGroup, resolution, skill) {
        // かすった相手には弱体を入れられない(サマナーズウォー方式の時だけ)
        if (resolution?.glancedTargets.has(target.instanceId))
            return false;
        /*
         * 才能による発動率の底上げ。**的中とは別物。**
         * 的中は相手の抵抗と引き算する値で、こちらは
         * スキルが元々持っている発動率(「65%で火傷」の65)そのものを動かす。
         *
         * **確率が書かれていない効果は素通り。**「常に試みる」ものを
         * 1より上へ押し上げても意味が無く、逆に「必ず入る」の意味が壊れる。
         */
        let procChance = baseChance ?? 1;
        if (baseChance !== undefined) {
            procChance += source.def.combatMods?.debuffChanceBonus ?? 0;
            for (const entry of skill?.talentMods?.debuffChanceWhen ?? []) {
                if (evaluateTargetCondition(entry.when, source, target))
                    procChance += entry.value;
            }
            procChance = Math.max(0, Math.min(1, procChance));
        }
        const groupKey = chanceGroup && resolution ? `${target.instanceId}:${chanceGroup}` : undefined;
        if (groupKey) {
            const cached = resolution.chanceGroups.get(groupKey);
            if (cached !== undefined)
                return cached;
        }
        if (this.rng() >= procChance) {
            if (groupKey)
                resolution.chanceGroups.set(groupKey, false);
            return false;
        }
        /*
