    if (remaining > 0 && from.shieldTurns > 0) {
        to.shieldValue = Math.max(to.shieldValue, from.shieldValue);
        to.shieldTurns = Math.max(to.shieldTurns, from.shieldTurns);
        from.shieldValue = 0;
        from.shieldTurns = 0;
