    for (const type of SET_TYPES) {
        const count = counts[type] ?? 0;
        const config = SET_BONUS_CONFIG[type];
        if (count >= SET_PIECE_COUNTS.TWO)
            applyStatEffect(bonus, config.two);
        if (count >= SET_PIECE_COUNTS.FOUR)
            applyStatEffect(bonus, config.four);
    }
    return bonus;
