    const counts = getEquippedSetCounts(equipmentList);
    const mods = { ...DEFAULT_COMBAT_MODIFIERS };
    for (const type of SET_TYPES) {
        const count = counts[type] ?? 0;
        const config = SET_BONUS_CONFIG[type];
        if (count >= SET_PIECE_COUNTS.TWO)
            applyCombatEffect(mods, config.two);
        if (count >= SET_PIECE_COUNTS.FOUR)
            applyCombatEffect(mods, config.four);
