/**
 * 移し替えたスキルの実体を引く関数。
 *
 * `core` から `data` を直接参照すると層が逆流するので、
 * 起動時に `data` 側から差し込む(`setCreatedSkillResolver`)。
 */
let createdSkillResolver = null;
let latentAbilityResolver = null;
export function setCreatedSkillResolver(resolver) {
    createdSkillResolver = resolver;
}
