    switch (effect.kind) {
        case "CURSE": return `${Math.round(effect.chance * 100)}%で呪い1個(対象の2回目のターン開始時、付与時攻撃力×4の固定ダメージと1ターンスタン)`;
        case "DETONATE_CURSES": return "対象の呪いをすべて即時発動";
        case "CONVERT_CURSES": return `${Math.round(effect.chance * 100)}%で対象の強化をすべて呪いへ変換。成功時1ターンスタン`;
        case "DAMAGE_BOOST": return `与ダメージ+${Math.round(effect.amount * 100)}%(${effect.durationTurns}ターン)`;
        // **「対象以外へ」と書く。**対象を含めると、本命に二重で入るように読める
        case "SPLASH": return `対象に与えたダメージの${Math.round(effect.ratio * 100)}%を対象以外の敵全体へ拡散`;
        case "DAMAGE": {
            const scaleText = effect.scaleBonus
                ? `(自身の${SCALE_BONUS_STAT_JA[effect.scaleBonus.stat]}が高いほど上昇)`
                : effect.hpCoefficient !== undefined
                    ? `(最大HPの${percent(effect.hpCoefficient)}を加算)`
                    : effect.defCoefficient !== undefined
                        ? `(防御力の${percent(effect.defCoefficient)}を加算)`
                        : "";
            const ignoreDefenseText = effect.ignoreDefense
                ? "(防御力無視)"
                : effect.ignoreDefenseRatio
                    ? `(防御力${Math.round(effect.ignoreDefenseRatio * 100)}%無視)`
                    : "";
            const hpBonusText = (effect.targetHpBonus ?? [])
                .map((tier) => ` 対象HP${Math.round(tier.hpRatio * 100)}%以下で最終ダメージ+${Math.round(tier.bonus * 100)}%`)
                .join("");
            const hpIgnoreText = (effect.targetHpIgnoreDefense ?? [])
                .map((tier) => ` 対象HP${Math.round(tier.hpRatio * 100)}%以下で防御力${Math.round(tier.ratio * 100)}%無視`)
                .join("");
            const condBonusText = (effect.conditionalBonus ?? [])
                .map((entry) => ` ${EFFECT_CONDITION_JA[entry.when]}最終ダメージ+${Math.round(entry.bonus * 100)}%`)
                .join("");
            const missingText = effect.missingHpBonus
                ? ` 自身が失ったHPが多いほど最終ダメージ上昇(最大+${Math.round(effect.missingHpBonus.maxBonus * 100)}%)`
                : "";
            const debuffBonusText = effect.debuffDamageBonus
                ? ` 対象の弱体効果1個につき最終ダメージ+${Math.round(effect.debuffDamageBonus.perDebuff * 100)}%(最大+${Math.round(effect.debuffDamageBonus.maxBonus * 100)}%)`
                : "";
            const critGaugeText = effect.gaugeOnCritPerHit
                ? ` 各ヒットのクリティカルで自身の行動ゲージ+${Math.round(effect.gaugeOnCritPerHit * 100)}%`
                : "";
            const special = [
                effect.critDamageBonus ? `会心時の最終ダメージ+${effect.critDamageBonus * 100}%` : '',
                effect.currentHpBonus ? `対象の現在HP割合が高いほど最終ダメージ上昇(最大+${effect.currentHpBonus * 100}%)` : '',
                effect.fullHpBonus ? `対象HP100%で最終ダメージ+${effect.fullHpBonus * 100}%` : '',
                effect.debuffIgnoreDefense ? `弱体${effect.debuffIgnoreDefense.count}個以上で防御${effect.debuffIgnoreDefense.ratio * 100}%無視` : '',
                effect.perHitEffects ? `各ヒットごとに: ${effect.perHitEffects.map(describeSkillEffect).join('、')}` : '',
            ].filter(Boolean).join('。');
            const requiresText = conditionPrefix(effect.requires);
            return `${requiresText}ダメージ倍率 ${effect.multiplier.toFixed(2)}倍${effect.hits && effect.hits > 1 ? ` × ${effect.hits}回` : ""}${scaleText}${ignoreDefenseText}${hpBonusText}${hpIgnoreText}${condBonusText}${missingText}${debuffBonusText}${critGaugeText}${special ? `。${special}` : ""}`;
        }
        case "HEAL": {
            const who = effect.applyTo === "SELF" ? "自身を" : effect.applyTo === "ALLIES" ? "味方全体を" : "";
            if (effect.scaleStat === "hp")
                return `${who}回復 術者の最大HPの${Number((effect.healRate * 100).toFixed(2))}%`;
            if (effect.scaleStat === "atk")
                return `${who}回復 自身の攻撃力の${(effect.healRate * 100).toFixed(0)}%`;
            if (effect.scaleStat === "def")
                return `${who}回復 自身の防御力の${(effect.healRate * 100).toFixed(0)}%`;
            return `${who}回復 最大HPの${(effect.healRate * 100).toFixed(1)}%`;
        }
        case "LIFESTEAL":
            return `与えたダメージの${(effect.healRate * 100).toFixed(0)}%を自身が回復${effect.maxSourceHpRate === undefined ? "" : ` (自身の最大HPの${effect.maxSourceHpRate * 100}%まで)`}`;
        case "BUFF": {
            const scope = effect.applyTo === "ALLIES" ? "味方全体の" : effect.applyTo === "SELF" ? "自身の" : "";
            return `${scope}${BUFF_STAT_JA[effect.stat]}+${Math.round(effect.amount * 100)}% (${effect.durationTurns}ターン)`;
        }
        case "DEBUFF":
            return `${chanceSuffix(effect.chance)}${BUFF_STAT_JA[effect.stat]}-${Math.round(effect.amount * 100)}% (${effect.durationTurns}ターン)`;
        case "STATUS": {
            const scope = effect.applyTo === "ALLIES" ? "味方全体に" : effect.applyTo === "SELF" ? "自身に" : "";
            return `${chanceSuffix(effect.chance)}${scope}${STATUS_EFFECT_JA[effect.status]} (${effect.durationTurns}ターン)`;
        }
        case "STUN":
            return `${conditionPrefix(effect.requires)}${chanceSuffix(effect.chance)}スタン (${effect.durationTurns}ターン)`;
        case "BURN":
            return `${chanceSuffix(effect.chance)}火傷 (${effect.durationTurns}ターン、自身のターン終了時に自身の攻撃力分のダメージ)`;
        case "GAUGE": {
            const scope = effect.applyTo === "ALLIES" ? "味方全体の" : effect.applyTo === "SELF" ? "自身の" : "";
            const extra = effect.conditionalExtra
                ? ` (${EFFECT_CONDITION_JA[effect.conditionalExtra.when]}さらに${Math.round(Math.abs(effect.conditionalExtra.amount) * 100)}%)`
                : effect.lowHpExtra
                    ? ` (HP${Math.round(effect.lowHpExtra.hpRatio * 100)}%以下ならさらに${Math.round(effect.lowHpExtra.amount * 100)}%)`
                    : "";
            const head = conditionPrefix(effect.requires);
            if (effect.drain)
                return `${head}${chanceSuffix(effect.chance)}${scope}行動ゲージを${Math.round(effect.amount * 100)}%吸収${extra}`;
            /*
             * **100%を超える指定は、100%と書く。**
             *
             * ゲージは0〜100%の間に収まる(`engine.ts` が両端で止める)ので、
             * -118% と -100% では起きることが同じ。スキルを上げると量も伸びる作りなので、
             * 「-100%」と書いた技がMAXで「-118%」と表示され、**足りない数字を
             * 盛ったように見えていた**。実際に起きることだけを書く。
             */
            const shown = Math.min(1, Math.abs(effect.amount));
            const verb = effect.amount >= 0 ? `+${Math.round(shown * 100)}%` : `-${Math.round(shown * 100)}%`;
            return `${head}${chanceSuffix(effect.chance)}${scope}行動ゲージ${verb}${extra}`;
        }
        case "SHIELD": {
            const scope = effect.applyTo === "ALLIES" ? "味方全体に" : effect.applyTo === "SELF" ? "自身に" : "";
            const base = effect.fromSourceHp ? "自身の最大HP" : "最大HP";
            return `${scope}シールド ${base}の${Math.round(effect.shieldRate * 100)}% (${effect.durationTurns}ターン、ダメージを肩代わり)`;
        }
        case "IMMUNITY":
            return `状態異常無効 (${effect.durationTurns}ターン)`;
        case "REGEN":
            return `継続回復 最大HPの${(effect.healRate * 100).toFixed(1)}% (${effect.durationTurns}ターン、自身のターン開始時)`;
        case "CLEANSE": {
            const scope = effect.applyTo === "ALLIES" ? "味方全体の" : effect.applyTo === "SELF" ? "自身の" : "";
            return effect.count === undefined ? `${scope}デバフを解除` : `${scope}デバフを${effect.count}個解除`;
        }
        case "STRIP":
            return effect.count === undefined
                ? `${conditionPrefix(effect.requires)}${chanceSuffix(effect.chance)}有利な効果(シールド・無効・能力上昇)を解除`
                : `${conditionPrefix(effect.requires)}${chanceSuffix(effect.chance)}有利な効果を${effect.count}個解除`;
        case "STEAL_BUFF":
            return `${chanceSuffix(effect.chance)}有利な効果を${effect.count ?? 1}個奪って自身に付与`;
        case "MITIGATE": {
            const scope = effect.applyTo === "ALLIES" ? "味方全体の" : effect.applyTo === "SELF" ? "自身の" : "";
            const extra = effect.vsTauntedExtra ? `(挑発状態の敵からはさらに${Math.round(effect.vsTauntedExtra * 100)}%軽減)` : "";
            return `${scope}受けるダメージ-${Math.round(effect.amount * 100)}% (${effect.durationTurns}ターン)${extra}`;
        }
        case "PROTECT":
            return `保護 (${effect.durationTurns}ターン、対象が受けるダメージの${Math.round(effect.share * 100)}%を自身が肩代わり)`;
        case "COUNTER_STANCE": {
            const hp = effect.hpCoefficient ? `(最大HPの${percent(effect.hpCoefficient)}を加算)` : "";
            const heal = effect.healRate ? ` 反撃のたび自身のHPを最大HPの${Math.round(effect.healRate * 100)}%回復` : "";
            return `${effect.durationTurns}ターン、攻撃を受けるたび攻撃者へ攻撃力${effect.multiplier.toFixed(2)}倍の反撃${hp}${heal}`;
        }
        case "COOLDOWN_REDUCE": {
            const scope = effect.applyTo === "ALLIES" ? "味方全体の" : effect.applyTo === "SELF" ? "自身の" : "";
            return `${scope}全スキルのクールタイムを${effect.turns}ターン短縮`;
        }
        case "COOP_ATTACK": {
            const cd = effect.allyCooldownReduce ? `(参加した味方のクールタイム-${effect.allyCooldownReduce})` : "";
            return `味方${effect.allies}体とともに同じ相手へスキル1で協力攻撃${cd}`;
        }
        case "GAUGE_ON_HIT":
            return `${effect.durationTurns}ターン、攻撃を受けるたび行動ゲージ+${Math.round(effect.amount * 100)}%`;
        case "HEAL_BLOCK":
            return `${chanceSuffix(effect.chance)}治癒阻害 (${effect.durationTurns}ターン、受ける回復が${Math.round((1 - effect.healMultiplier) * 100)}%減る)`;
        case "COOLDOWN_EXTEND":
            return `${chanceSuffix(effect.chance)}敵の全スキルのクールタイムを${effect.turns}ターン延長`;
        case "BLIND":
            return `${chanceSuffix(effect.chance)}暗闇 (${effect.durationTurns}ターン、攻撃時50%でダメージ-75%・追加効果なし)`;
        case "POISON": {
            const stacks = effect.stacks && effect.stacks > 1 ? `${effect.stacks}スタック` : "1スタック";
            const extra = effect.extraStacksIfPoisoned ? ` (既に毒状態ならさらに${effect.extraStacksIfPoisoned}スタック)` : "";
            return `${conditionPrefix(effect.requires)}${chanceSuffix(effect.chance)}毒${stacks} (1スタックにつき最大HPの${Math.round(effect.damageRatePerStack * 100)}%、最大5スタック、${effect.durationTurns}ターン)${extra}`;
        }
    }
}
/**
 * UI表示用に、スキル1つの中身を行の配列にする。
 * パッシブはそのレベルの中身を1行で返す(効果の配列を持たないため)。
 */
export function describeSkillLines(skill) {
    if (skill.passive)
        return [describePassiveLevel(passiveAtLevel(skill.passive, skill.passiveLevel ?? 1))];
    return [...skill.effects.map(describeSkillEffect),
        ...(skill.extraTurn ? ['使用後、即時に追加ターンを獲得'] : []),
        ...(skill.resetCooldownOnKill ? ['このスキルで1体以上倒すと、このスキルのCTを全回復'] : []),
        ...(skill.gaugeIfThreeEnemies ? [`敵が3体以上いる時、自身の行動ゲージ+${skill.gaugeIfThreeEnemies * 100}%`] : []),
    ];
}

import { ATK_UP, DEF_UP, SPD_UP, ATK_DOWN, DEF_DOWN } from "./statusValues.js";
/** 9月の合意済み調整。実体化時に適用し、所持済み・継承済みの技にも反映する。 */
export function applySeptemberSkillBalance(skill) {
    const change = (description, effects, rest = {}) => ({ ...skill, description, effects, ...rest });
    switch (skill.id) {
        case "golem_s2_c": return change("敵単体に攻撃力1.5倍のダメージ。85%で防御力を50%低下させる(2ターン)。", [
            { kind: "DAMAGE", multiplier: 1.5 }, { kind: "DEBUFF", stat: "def", amount: DEF_DOWN, chance: 0.85, durationTurns: 2 }
        ]);
        case "abyssreaper_s2_c": return change("敵単体の強化を1個奪い、行動ゲージを50%減少。さらに強化阻害と毒1スタックをそれぞれ90%で2ターン付与する。", [
            { kind: "STEAL_BUFF", count: 1 }, { kind: "GAUGE", amount: -0.5 },
            { kind: "STATUS", status: "BUFF_BLOCK", chance: 0.9, durationTurns: 2 },
            { kind: "POISON", damageRatePerStack: 0.05, stacks: 1, chance: 0.9, durationTurns: 2 }
        ]);
        case "kobold_s2_b": return change("敵単体に攻撃力1.75倍のダメージ。対象のHPが50%以下なら最終ダメージが33%増加。行動ゲージを30%吸収する。", [
            { kind: "DAMAGE", multiplier: 1.75, targetHpBonus: [{ hpRatio: 0.5, bonus: 0.33 }] }, { kind: "GAUGE", amount: 0.3, drain: true }
        ]);
        case "mushroon_s2_a": return change("敵全体に攻撃力0.75倍のダメージ。75%で毒2スタックを2ターン付与する。", [
            { kind: "DAMAGE", multiplier: 0.75 }, { kind: "POISON", damageRatePerStack: 0.05, stacks: 2, chance: 0.75, durationTurns: 2 }
        ]);
        case "mimic_s2_a": return change("敵単体に攻撃力1.8倍＋自身の最大HP×0.08のダメージ。与えたダメージの40%を回復し、自身のHPが50%以下なら吸血率が20ポイント増加する。", skill.effects.map(e => e.kind === "DAMAGE" ? { ...e, multiplier: 1.8 } : e));
        /*
         * **大地踏みの最大HP比例は、ここに書いた値が本番になる。**
         * `star5.ts` 側の 0.12 は実体化の時にこの差し替えで上書きされるので、
         * 片方だけ直すと効かない。全体攻撃なので、単体主力の「巨体の圧力」(0.20)
         * より低く置く——ここを揃えると単体で殴る理由が消える。
         */
        case "behemoth_s2_a": return change("敵全体に攻撃力0.8倍＋自身の最大HP×0.12のダメージ。70%で攻撃力を50%低下させる(2ターン)。行動ゲージを30%減少させる。", [
            { kind: "DAMAGE", multiplier: 0.8, hpCoefficient: 0.12 },
            { kind: "DEBUFF", stat: "atk", amount: ATK_DOWN, chance: 0.7, durationTurns: 2 }, { kind: "GAUGE", amount: -0.3 }
        ]);
        case "kobold_s3_a": return change("敵単体に攻撃力2.3倍のダメージ。攻撃前の対象HPが30%以下なら防御力を完全に無視する。", [
            { kind: "DAMAGE", multiplier: 2.3, targetHpIgnoreDefense: [{ hpRatio: 0.3, ratio: 1 }] }
        ]);
        case "wisp_s3_c": return change("味方単体の行動ゲージを80%進め、速度を20%上昇させる(2ターン)。最大レベルでゲージ100%、速度3ターン、CT3。", [
            { kind: "GAUGE", amount: 0.8 }, { kind: "BUFF", stat: "spd", amount: SPD_UP, durationTurns: 2 }
        ], {
            target: "SINGLE_ALLY", cooldownTurns: 4, maxLevelOverride: { cooldownTurns: 3, effects: [
                    { kind: "GAUGE", amount: 1 }, { kind: "BUFF", stat: "spd", amount: SPD_UP, durationTurns: 3 }
                ] }
        });
        case "valkyria_s3_b": return change("味方全体の行動ゲージを30%進め、速度を20%・攻撃力を30%上昇させる(2ターン)。", [
            { kind: "GAUGE", amount: 0.3 }, { kind: "BUFF", stat: "spd", amount: SPD_UP, durationTurns: 2 },
            { kind: "BUFF", stat: "atk", amount: ATK_UP, durationTurns: 2 }
        ]);
        case "fairy_s1": return change("敵単体に攻撃力0.7倍のダメージを与え、自身の最大HPの2%を回復。最大レベルでは1.0倍・4%回復。", skill.effects, {
            maxLevelOverride: { effects: [{ kind: "DAMAGE", multiplier: 1 }, { kind: "HEAL", healRate: 0.04, applyTo: "SELF" }] }
        });
        case "mimic_s3_b": return { ...skill, maxLevelOverride: { cooldownTurns: 3 } };
        case "golem_s3_c": return { ...skill, description: skill.description + "最大レベルで自身に3ターン反射も付与する。", maxLevelOverride: { effects: [
                    { kind: "BUFF", stat: "atk", amount: ATK_UP, durationTurns: 3 }, { kind: "BUFF", stat: "def", amount: DEF_UP, durationTurns: 3 },
                    { kind: "STATUS", status: "REFLECT", durationTurns: 3, applyTo: "SELF" }
                ] } };
        case "griffon_s3_c": return { ...skill, description: skill.description + "さらに味方全体の行動ゲージを15%進める。", effects: [...skill.effects, { kind: "GAUGE", amount: 0.15 }] };
        case "treant_s2_c": return { ...skill, description: skill.description + "回復量は自身の最大HPの30%まで。最大レベルでは攻撃力1.5倍＋最大HP×0.12のダメージ。",
            effects: skill.effects.map(e => e.kind === "LIFESTEAL" ? { ...e, maxSourceHpRate: 0.3 } : e),
            // Lv5の差し替え側にも同じ2倍を掛ける。ここを忘れると「育てると比例が痩せる」
            maxLevelOverride: { effects: [{ kind: "DAMAGE", multiplier: 1.5, hpCoefficient: 0.12 }, { kind: "LIFESTEAL", healRate: 0.472, maxSourceHpRate: 0.3 }] } };
        case "mushroon_s3_dark": return { ...skill, description: skill.description + "最大レベルでは全体0.5倍の3回攻撃になり、各攻撃後65%で毒1スタックを3ターン付与する。弱体数による威力増加は維持する。",
            maxLevelOverride: { effects: Array.from({ length: 3 }, () => [
                    { kind: "DAMAGE", multiplier: 0.5, debuffDamageBonus: { perDebuff: 0.06, maxBonus: 0.3 } },
                    { kind: "POISON", damageRatePerStack: 0.059, stacks: 1, chance: 0.65, durationTurns: 3 }
                ]).flat() } };
        case "kobold_s3_c": return { ...skill, description: "パッシブ。HP50%以下の敵への最終ダメージが20%上昇し、常時攻撃力25%・速度15が上昇。すべての攻撃に速度比例の威力を加算する(速度200で攻撃力0.15倍ぶん)。",
            passive: skill.passive && { ...skill.passive, levels: skill.passive.levels.map(e => e.kind === "SCENT_OF_PREY" ? { ...e, damageUp: 0.2, atkUp: 0.25, spd: 15, speedCoefficient: 0.15 } : e) } };
        default: return skill;
    }
}

/** 弱体扱いする効果。ここに無いものは弱化成功率の才能が乗らない */
const DEBUFF_KINDS = new Set([
    "DEBUFF", "STUN", "BURN", "POISON", "BLIND", "HEAL_BLOCK", "COOLDOWN_EXTEND",
]);
/** 強化扱いする効果 */
const BUFF_KINDS = new Set([
    "BUFF", "IMMUNITY", "REGEN", "MITIGATE", "PROTECT", "COUNTER_STANCE",
]);
/**
 * その効果が「味方へ向く」か。
 *
 * `applyTo` が付いていれば従い、無ければスキルの対象で決まる。
 * **敵を殴る技に置かれた回復は必ず applyTo を持つ**(そう書く決まりになっている)。
 */
function towardAllies(effect, skill) {
    const applyTo = "applyTo" in effect ? effect.applyTo : undefined;
    if (applyTo === "SELF" || applyTo === "ALLIES" || applyTo === "LOWEST_HP_ALLY")
        return true;
    return skill.target === "SINGLE_ALLY" || skill.target === "ALL_ALLIES" || skill.target === "SELF";
}
/**
 * そのスキルの札を出す。
 *
 * **パッシブ枠には何も付けない。**手番で使う技ではないので、
 * 「使用後にゲージ+10%」のような才能が意味を成さない。
 */
export function skillTags(skill) {
    const tags = new Set();
    if (skill.passive !== undefined || skill.automatic === true)
        return tags;
    for (const effect of skill.effects) {
        switch (effect.kind) {
            case "DAMAGE":
                tags.add("attack");
                break;
            case "HEAL":
            case "LIFESTEAL":
                tags.add("heal");
                break;
            case "SHIELD":
                tags.add("shield");
                break;
            case "GAUGE":
                /*
                 * **増やすか減らすかは符号で決まる。**
                 * 「敵のゲージを減らす」も「味方のゲージを進める」も同じ GAUGE なので、
                 * 向き先まで見ないと、減らす技に増加量の才能が並ぶ。
                 */
                if (effect.amount > 0 && towardAllies(effect, skill))
                    tags.add("gauge_up");
                else if (effect.amount < 0)
                    tags.add("gauge_down");
                else if (effect.drain)
                    tags.add("gauge_down");
                break;
            case "STRIP":
                tags.add("debuff");
                break;
            default:
                if (DEBUFF_KINDS.has(effect.kind))
                    tags.add("debuff");
                else if (BUFF_KINDS.has(effect.kind))
                    tags.add("buff");
                else if (effect.kind === "STATUS") {
                    // STATUS は中身で強化にも弱体にもなる。向き先で振り分ける
                    if (towardAllies(effect, skill))
                        tags.add("buff");
                    else
                        tags.add("debuff");
                }
                break;
        }
    }
    switch (skill.target) {
        case "SINGLE_ENEMY":
            tags.add("single");
            tags.add("enemy_target");
            break;
        case "ALL_ENEMIES":
            tags.add("aoe");
            tags.add("enemy_target");
            break;
        case "SINGLE_ALLY":
            tags.add("single");
            tags.add("ally_target");
            break;
        case "ALL_ALLIES":
            tags.add("aoe");
            tags.add("ally_target");
            break;
        case "SELF":
            tags.add("single");
            tags.add("self_target");
            break;
    }
    return tags;
}

export function cloneStats(stats) {
    return { ...stats };
}
/** UI表示用に、クリ率・クリダメ・状態異常付与率・抵抗率を短い日本語テキストの配列に変換する */
export function formatExtraStatLines(stats) {
    return [
        `クリ率 ${Math.round(stats.criRate * 100)}%`,
        `クリダメ +${Math.round((stats.criDmg - 1) * 100)}%`,
        `状態異常付与率 ${Math.round(stats.accuracy * 100)}%`,
        `状態異常抵抗率 ${Math.round(stats.resistance * 100)}%`,
    ];
}
const INT_STAT = (key, label) => ({
    key,
    label,
    toInt: (s) => Math.round(s[key]),
    unit: "",
});
const PERCENT_STAT = (key, label) => ({
    key,
    label,
    toInt: (s) => Math.round(s[key] * 100),
    unit: "%",
});
/** HP・攻撃・防御・速度。強さを判断する時にまず見る4項目 */
export const PRIMARY_STAT_FORMATS = [
    INT_STAT("hp", "HP"),
    INT_STAT("atk", "攻撃力"),
    INT_STAT("def", "防御力"),
    INT_STAT("spd", "速度"),
];
/** クリ率・クリダメ・状態異常の付与率と抵抗率 */
export const EXTRA_STAT_FORMATS = [
    PERCENT_STAT("criRate", "クリ率"),
    // クリダメだけは1.5倍を「+50%」と見せる決まりなので、100倍ではなく「(倍率-1)の100倍」
    { key: "criDmg", label: "クリダメ", toInt: (s) => Math.round((s.criDmg - 1) * 100), unit: "%", prefix: "+" },
    PERCENT_STAT("accuracy", "状態異常付与率"),
    PERCENT_STAT("resistance", "状態異常抵抗率"),
];
/**
 * 素のステータスと装備込みのステータスを突き合わせて、項目ごとの内訳を作る。
 *
 * 装備を着けた後の合計値しか出していなかったため、
 * **その数字のうちどれだけが装備のおかげなのかが分からなかった**。
 * 装備を組み替える判断はこの差分を見てするものなので、分けて持たせる。
 */
export function buildStatBreakdown(base, total, formats) {
    return formats.map((f) => {
        const baseInt = f.toInt(base);
        const totalInt = f.toInt(total);
        const diff = totalInt - baseInt;
        const show = (value) => `${f.prefix ?? ""}${value}${f.unit}`;
        return {
            key: f.key,
            label: f.label,
            total: show(totalInt),
            base: show(baseInt),
            gain: diff === 0 ? null : `${diff > 0 ? "+" : "−"}${Math.abs(diff)}${f.unit}`,
        };
    });
}
/**
 * 戦闘の札に出すHPの整形。
 *
 * **4桁までしか想定していなかった。**★6Lv60に装備を積むとHPは5桁に届き
 * (実測でボス178,668)、札の幅(最大124px)に「現在/最大」が収まらず、
 * 左右が切れて `7523/17866` のように**数字そのものが化けて見えていた**。
 * 現在値が最大値より大きい、という有り得ない表示になっていた。
 *
 * 札を広げる手は採れない。4体が横に並ぶので、1枚を広げると隣とぶつかり、
 * 実測で横画面の右半分が札の壁になって体が隠れた。
 *
 * そこで**桁が増えても文字数が増えない**形にする。
 * 1万を超えたら「万」で丸める。正確な値は title 属性に残してあるので、
 * 必要なら長押しで読める。
 */
export function formatHp(value) {
    const n = Math.max(0, Math.round(value));
    if (n < 10_000)
        return String(n);
    const man = n / 10_000;
    // 100万を超えたら小数を落とす。「123.4万」は札からはみ出す。
    // **丸めた後で判定する。**99.99を先に判定すると「100.0万」になって1文字はみ出す
    return Number(man.toFixed(1)) >= 100 ? `${Math.round(man)}万` : `${man.toFixed(1)}万`;
}
/** 札に出す「現在/最大」。どちらも同じ規則で丸める */
export function formatHpPair(current, max) {
    return `${formatHp(current)}/${formatHp(max)}`;
}

/**
 * **通常のバフ・デバフの効果量。ここが唯一の置き場所。**
