export function isSkillTalentApplicable(id, tags) {
    const def = ALL_BY_ID.get(id);
    if (!def)
        return false;
    return def.requiresTags.every((tag) => tags.has(tag));
}

/**
 * 初期★ごとの才能pt上限。
 *
 * **★が低いほど多い。** 引きやすさの差を、育て切った時の伸びしろで埋め戻す。
 */
export const TALENT_POINT_CAP = {
    3: 20,
    4: 15,
    5: 11,
