/**
 * 追加11種の潜在覚醒。**66個体 × 3候補 = 198個。**
 *
 * ## なぜ自動生成に混ぜないのか
 *
 * 既存72個体の潜在は `src/data/latentAbilities.ts` が機械的に配っている。
 * あちらは「どの種族にも当てはまる汎用の3方向」を配る作りなので、
 * **その種族のスキル1が何をするかを見ていない。**
 *
 * 今回の11種は、依頼主が**スキル1ごとに噛み合う強化**を指定している
 * (毒を入れた時・速度を落とした時・挑発した時・解除に成功した時)。
 * 汎用の配り方ではその指定を表現できないので、ここに書き下ろす。
 *
 * ## 何を優先しているか
 *
 * 依頼主の指定どおり、**低確率で体感しづらいものを増やさない。**
 * ほとんどが「条件を満たせば必ず起きる」か「100%の小さな効果」で、
 * 確率に頼るものは元のスキル1の判定に相乗りしている。
 */
/* ---------- 効果の短縮記法。1行に収めるためだけの道具 ---------- */
const G = (value) => ({ kind: "SELF_GAUGE", value });
const H = (value) => ({ kind: "SELF_HEAL", value });
const LS = (value) => ({ kind: "LIFESTEAL", value });
const CL = (count) => ({ kind: "SELF_CLEANSE", count });
const SSH = (value, duration) => ({ kind: "SELF_SHIELD", value, duration });
const AH = (value) => ({ kind: "LOWEST_ALLY_HEAL", value });
const AG = (value, whenAllyHpBelow, extra) => ({ kind: "LOWEST_ALLY_GAUGE", value, whenAllyHpBelow, extra });
const ACL = (count) => ({ kind: "LOWEST_ALLY_CLEANSE", count });
const ASH = (value, duration) => ({ kind: "LOWEST_ALLY_SHIELD", value, duration });
const AMT = (value, duration) => ({ kind: "LOWEST_ALLY_MITIGATE", value, duration });
const ABF = (stat, amount, duration) => ({ kind: "LOWEST_ALLY_BUFF", stat, amount, duration });
const ALLH = (value) => ({ kind: "ALLY_HEAL", value });
const ALLG = (value) => ({ kind: "ALLY_GAUGE_UP", chance: 1, value });
const TG = (value) => ({ kind: "GAUGE_DOWN", chance: 1, value });
const STEAL = (count) => ({ kind: "STEAL_BUFF", count });
const DRAIN = (value) => ({ kind: "GAUGE_DRAIN_SHARE", value });
const DB = (status, duration) => ({ kind: "DEBUFF", status, chance: 1, duration });
/* ---------- 条件の短縮記法 ---------- */
const on = (status) => ({ kind: "ON_APPLIED", status });
const crit = (atLeast) => ({ kind: "ON_CRIT", atLeast });
const kill = { kind: "ON_KILL" };
const below = (ratio) => ({ kind: "TARGET_HP_BELOW", ratio });
const state = (s) => ({ kind: "TARGET_STATE", state: s });
function build(templateId, element, index, draft) {
    return {
        id: `${templateId}_${element}_latent_${index}`,
        name: draft.name,
        description: draft.description,
        skillSlot: 0,
        category: draft.category ?? "OFFENSE",
        effectType: draft.hpScale !== undefined ? "HP_SCALING" : draft.defScale !== undefined ? "DEF_SCALING" : "DAMAGE_UP",
        value: draft.hpScale ?? draft.defScale ?? 0,
        chance: 1,
        duration: 0,
        target: "TARGET",
        resolution: "ALWAYS",
        runtimeEffects: draft.effects,
        condition: draft.condition,
        internalCooldown: draft.internalCooldown,
        flatDamageBonus: draft.flat,
        damageBonusWhen: draft.when,
        replaceTargetHpBonus: draft.hpTiers,
        addTargetHpIgnoreDefense: draft.hpIgnore,
        scaleBonusAdd: draft.scale,
        gaugeAmountOverride: draft.gaugeOverride,
        chanceBonus: draft.chanceBonus,
        chargeOnHit: draft.chargeOnHit,
        chargeOnCrit: draft.chargeOnCrit,
        critDmgGrowth: draft.critDmgGrowth,
        oneShotMitigate: draft.oneShotMitigate,
        debuffDamageBonus: draft.debuffBonus,
        ignoreDefenseRatio: draft.ignoreDef,
        splashRatioBonus: draft.splash,
        damageEffectIndex: draft.damageIndex,
        hpMultiplier: draft.hpMul,
        defMultiplier: draft.defMul,
        grade: "A",
    };
}
